"""JSON entry point used by the web worker."""
import json
import traceback
from typing import Any, Dict, List

import sympy as sp

from . import basic, cmd_algebra, cmd_calculus, cmd_math, cmd_matrix, cmd_prob, latexin, printer  # noqa: F401
from .core import ENGINE, Ctx, evaluate, is_mat
from .parser import TIError, split_statements
from .values import NeedInput, TList, TStr, UFunc

try:
    from . import cmd_finance, cmd_stats  # noqa: F401
except ImportError:
    pass

OPS: Dict[str, Any] = {}


def op(name: str) -> Any:
    def deco(fn: Any) -> Any:
        OPS[name] = fn
        return fn

    return deco


def kind_of(v: Any) -> str:
    if isinstance(v, UFunc):
        return 'prgm' if v.kind == 'prgm' else 'func'
    if isinstance(v, TList):
        return 'list'
    if isinstance(v, TStr):
        return 'str'
    if is_mat(v):
        return 'mat'
    if isinstance(v, sp.logic.boolalg.Boolean):
        return 'bool'
    return 'num' if isinstance(v, sp.Expr) and v.is_number else 'expr'


def run_source(ctx: Ctx, text: str) -> Any:
    if basic.define_program(ctx, text):
        return None
    value: Any = None
    for stmt in split_statements(text) or ['']:
        value = evaluate(ctx, stmt)
    return value


@op('eval')
def op_eval(req: Dict[str, Any]) -> Dict[str, Any]:
    src = str(req.get('src', ''))
    is_latex = bool(req.get('latex'))
    ctx = Ctx(str(req.get('ns', 'default')), approx=bool(req.get('approx')), inputs=[str(i) for i in req.get('inputs') or []])
    printer.DIGITS[0] = ENGINE.digits
    out: Dict[str, Any] = {'ok': False, 'inLatex': src if is_latex else '', 'inText': src, 'outLatex': '', 'outText': ''}
    try:
        text = latexin.to_text(src) if is_latex else src
        out['inText'] = text
        value = run_source(ctx, text)
        if value is not None and not isinstance(value, UFunc):
            ctx.vars['ans'] = value
        out.update(ok=True, outText=printer.to_text(value), outLatex=printer.to_latex(value))
    except NeedInput as need:
        out.update(ok=True, needInput={'prompt': need.prompt, 'kind': need.kind})
    except TIError as exc:
        out['error'] = str(exc)
    except RecursionError:
        out['error'] = 'Resource: expression too complex'
    except ZeroDivisionError:
        out['error'] = 'Domain: division by zero'
    except (NotImplementedError, sp.PolynomialError):
        out['error'] = 'Unable to evaluate'
    except Exception as exc:
        out['error'] = f'Error: {type(exc).__name__}: {exc}'[:160]
        out['trace'] = traceback.format_exc()[-600:]
    out['changed'] = ctx.changed
    out['disp'] = ctx.disp
    if ctx.clear_history:
        out['clearHistory'] = True
    return out


@op('python')
def op_python(req: Dict[str, Any]) -> Dict[str, Any]:
    ctx = Ctx(str(req.get('ns', 'default')), inputs=[str(i) for i in req.get('inputs') or []])
    out: Dict[str, Any] = {'ok': True, 'inLatex': '', 'inText': '', 'outLatex': '', 'outText': ''}
    try:
        basic.run_python(ctx, str(req.get('src', '')))
    except NeedInput as need:
        out['needInput'] = {'prompt': need.prompt, 'kind': need.kind}
    except TIError as exc:
        out.update(ok=False, error=str(exc))
    out['disp'] = ctx.disp
    return out


@op('vars')
def op_vars(req: Dict[str, Any]) -> Dict[str, Any]:
    printer.DIGITS[0] = ENGINE.digits
    items: List[Dict[str, str]] = []
    for name, v in sorted(ENGINE.space(str(req.get('ns', 'default'))).items()):
        if name == 'ans':
            continue
        preview = f"{name}({','.join(v.params)})" if isinstance(v, UFunc) else printer.to_text(v)
        items.append({'name': name, 'kind': kind_of(v), 'preview': preview[:60]})
    return {'vars': items}


@op('export_vars')
def op_export(req: Dict[str, Any]) -> Dict[str, Any]:
    printer.DIGITS[0] = 15
    out: List[Dict[str, str]] = []
    try:
        for name, v in sorted(ENGINE.space(str(req.get('ns', 'default'))).items()):
            if name == 'ans':
                continue
            if isinstance(v, UFunc):
                if v.src:
                    out.append({'name': name, 'src': v.src})
            else:
                out.append({'name': name, 'src': f'{name}:={printer.to_text(v)}'})
    finally:
        printer.DIGITS[0] = ENGINE.digits
    return {'vars': out}


@op('import_vars')
def op_import(req: Dict[str, Any]) -> Dict[str, Any]:
    ctx = Ctx(str(req.get('ns', 'default')))
    ok = True
    for item in req.get('vars') or []:
        try:
            run_source(ctx, str(item.get('src', '')))
        except Exception:
            ok = False
    return {'ok': ok, 'changed': True}


@op('set_mode')
def op_mode(req: Dict[str, Any]) -> Dict[str, Any]:
    ENGINE.angle = 'DEG' if req.get('angle') == 'DEG' else 'RAD'
    ENGINE.calc = req.get('calc') if req.get('calc') in ('AUTO', 'EXACT', 'APPROX') else 'AUTO'
    ENGINE.digits = max(1, min(12, int(req.get('digits') or 6)))
    printer.DIGITS[0] = ENGINE.digits
    return {'ok': True}


@op('drop_ns')
def op_drop(req: Dict[str, Any]) -> Dict[str, Any]:
    ENGINE.spaces.pop(str(req.get('ns', '')), None)
    return {'ok': True}


@op('reset')
def op_reset(req: Dict[str, Any]) -> Dict[str, Any]:
    ENGINE.spaces.clear()
    return {'ok': True}


@op('num_list')
def op_num_list(req: Dict[str, Any]) -> Dict[str, Any]:
    v = ENGINE.space(str(req.get('ns', 'default'))).get(str(req.get('name', '')).lower())
    if is_mat(v) and (v.rows == 1 or v.cols == 1):
        v = TList(list(v))
    if not isinstance(v, TList):
        return {'ok': False, 'values': [], 'error': 'List not found'}
    values: List[Any] = []
    for x in v:
        try:
            values.append(float(sp.N(x)))
        except (TypeError, ValueError):
            values.append(None)
    return {'ok': True, 'values': values}


def handle(request: str) -> str:
    req = json.loads(request)
    fn = OPS.get(req.get('op', ''))
    if fn is None:
        return json.dumps({'ok': False, 'error': f"Unknown op {req.get('op')}"})
    try:
        return json.dumps(fn(req), ensure_ascii=False)
    except Exception as exc:
        return json.dumps({'ok': False, 'error': f'{type(exc).__name__}: {exc}'[:200], 'inLatex': '', 'inText': '', 'outLatex': '', 'outText': ''})

sources.basic.py:
"""TI-Basic style programs/functions and the Python script runner."""
import builtins
import math
import random
import re
import sys
from typing import Any, Dict, List, Optional, Tuple

import sympy as sp

from .core import Ctx, ev, finalize, sym
from .parser import Node, TIError, parse_expr, parse_statement, split_statements
from .printer import to_text
from .values import Control, NeedInput, TStr, UFunc

DEFINE_RE = re.compile(r'^\s*Define\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(([^)]*)\)\s*=\s*(Func|Prgm)\b(.*)\bEnd(Func|Prgm)\s*$', re.S | re.I)
Block = List[Tuple[Any, ...]]


def first_word(line: str) -> str:
    m = re.match(r'[A-Za-z]+', line)
    return m.group().lower() if m else ''


def split_top(text: str) -> List[str]:
    parts, depth, cur, quoted = [], 0, '', False
    for ch in text:
        if ch == '"':
            quoted = not quoted
        if not quoted:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif ch == ',' and depth == 0:
                parts.append(cur)
                cur = ''
                continue
        cur += ch
    parts.append(cur)
    return parts


def compile_lines(lines: List[str]) -> Block:
    pos = [0]

    def block(stops: Tuple[str, ...]) -> Tuple[Block, str]:
        out: Block = []
        while pos[0] < len(lines):
            line = lines[pos[0]]
            word = first_word(line)
            if word in stops:
                return out, word
            pos[0] += 1
            out.append(statement(line, word))
        if stops:
            raise TIError(f'Syntax: missing {stops[-1]}')
        return out, ''

    def single() -> Block:
        if pos[0] >= len(lines):
            raise TIError('Syntax: statement expected after If')
        line = lines[pos[0]]
        pos[0] += 1
        return [statement(line, first_word(line))]

    def statement(line: str, word: str) -> Tuple[Any, ...]:
        rest = line[len(word):].strip()
        if word == 'if':
            if re.search(r'\bthen\s*$', rest, re.I):
                branches: List[Any] = [(parse_expr(re.sub(r'\bthen\s*$', '', rest, flags=re.I)), None)]
                otherwise: Optional[Block] = None
                while True:
                    body, stop = block(('elseif', 'else', 'endif'))
                    branches[-1] = (branches[-1][0], body)
                    stop_line = lines[pos[0]]
                    pos[0] += 1
                    if stop == 'elseif':
                        cond = re.sub(r'\bthen\s*$', '', stop_line[len('elseif'):].strip(), flags=re.I)
                        branches.append((parse_expr(cond), None))
                    elif stop == 'else':
                        otherwise, _ = block(('endif',))
                        pos[0] += 1
                        break
                    else:
                        break
                return ('if', branches, otherwise)
            return ('if', [(parse_expr(rest), single())], None)
        if word == 'for':
            parts = split_top(rest)
            if len(parts) not in (3, 4):
                raise TIError('Syntax: For Var, Low, High [,Step]')
            body, _ = block(('endfor',))
            pos[0] += 1
            return ('for', parts[0].strip().lower(), parse_expr(parts[1]), parse_expr(parts[2]), parse_expr(parts[3]) if len(parts) == 4 else None, body)
        if word == 'while':
            body, _ = block(('endwhile',))
            pos[0] += 1
            return ('while', parse_expr(rest), body)
        if word == 'loop':
            body, _ = block(('endloop',))
            pos[0] += 1
            return ('loop', body)
        if word == 'local':
            return ('local', [p.strip().lower() for p in split_top(rest) if p.strip()])
        if word in ('request', 'requeststr'):
            parts = split_top(rest)
            if len(parts) < 2:
                raise TIError('Syntax: Request "prompt", Var')
            return ('request', parse_expr(parts[0]), parts[1].strip().lower(), word == 'requeststr')
        if word == 'text':
            return ('text', parse_expr(rest))
        if word in ('func', 'prgm', 'endfunc', 'endprgm') and not rest:
            return ('nop',)
        return ('stmt', parse_statement(line), line)

    out, _ = block(())
    return out


def truth(ctx: Ctx, node: Node) -> bool:
    v = ev(ctx, node)
    if v is sp.true or v is True:
        return True
    if v is sp.false or v is False:
        return False
    try:
        s = sp.simplify(v)
        if s is sp.true:
            return True
        if s is sp.false:
            return False
    except Exception:
        pass
    raise TIError('Data type: condition must be true or false')


def read_input(ctx: Ctx, prompt: str, kind: str) -> str:
    if ctx.input_pos < len(ctx.inputs):
        ctx.input_pos += 1
        return ctx.inputs[ctx.input_pos - 1]
    raise NeedInput(prompt, kind)


def loop_body(ctx: Ctx, body: Block) -> bool:
    try:
        run_block(ctx, body)
    except Control as c:
        if c.kind == 'exit':
            return False
        if c.kind != 'cycle':
            raise
    return True


def run_block(ctx: Ctx, block: Block) -> None:
    for st in block:
        ctx.tick()
        kind = st[0]
        if kind == 'stmt':
            node = st[1]
            ctx.src = st[2]
            value = ev(ctx, node)
            if node[0] not in ('define', 'cmd') and ctx.frames:
                ctx.frames[-1]['#last'] = finalize(ctx, value, node)
        elif kind == 'if':
            for cond, body in st[1]:
                if truth(ctx, cond):
                    run_block(ctx, body)
                    break
            else:
                if st[2] is not None:
                    run_block(ctx, st[2])
        elif kind == 'for':
            _, var, lo, hi, step, body = st
            cur = finalize(ctx, ev(ctx, lo))
            end = ev(ctx, hi)
            inc = ev(ctx, step) if step is not None else sp.Integer(1)
            try:
                up = float(inc) >= 0
                while (float(cur) <= float(end) + 1e-12) if up else (float(cur) >= float(end) - 1e-12):
                    ctx.tick()
                    ctx.assign(var, cur)
                    if not loop_body(ctx, body):
                        break
                    cur = finalize(ctx, ctx.lookup(var) + inc)
            except (TypeError, ValueError):
                raise TIError('Data type: For bounds must be numbers')
        elif kind in ('while', 'loop'):
            body = st[2] if kind == 'while' else st[1]
            while kind == 'loop' or truth(ctx, st[1]):
                ctx.tick()
                if not loop_body(ctx, body):
                    break
        elif kind == 'local':
            if not ctx.frames:
                raise TIError('Syntax: Local is only valid in a program or function')
            for name in st[1]:
                ctx.frames[-1].setdefault(name, sym(name))
        elif kind == 'request':
            prompt = ev(ctx, st[1])
            text = read_input(ctx, str(prompt) if isinstance(prompt, TStr) else to_text(prompt), 'str' if st[3] else 'expr')
            ctx.assign(st[2], TStr(text) if st[3] else finalize(ctx, ev(ctx, parse_expr(text))))
            ctx.changed = True
        elif kind == 'text':
            v = ev(ctx, st[1])
            ctx.disp.append(str(v) if isinstance(v, TStr) else to_text(v))


def define_program(ctx: Ctx, src: str) -> bool:
    m = DEFINE_RE.match(src)
    if not m:
        return False
    name, params, kind, body = m.group(1).lower(), m.group(2), m.group(3).lower(), m.group(4)
    plist = [p.strip().lower() for p in params.split(',') if p.strip()]
    prog = compile_lines(split_statements(body))
    ctx.assign(name, UFunc(name, plist, prog=prog, kind=kind, src=src.strip()))
    ctx.changed = True
    return True


class _Limit:
    def __init__(self, limit: int):
        self.left = limit

    def __call__(self, frame: Any, event: str, arg: Any) -> Any:
        if event == 'line':
            self.left -= 1
            if self.left <= 0:
                raise TIError('Break: script stopped (too many steps)')
        return self


SAFE_NAMES = (
    'abs', 'all', 'any', 'bool', 'chr', 'dict', 'divmod', 'enumerate', 'filter', 'float', 'int', 'isinstance', 'len', 'list', 'map', 'max', 'min', 'ord', 'pow', 'range', 'reversed', 'round',
    'set', 'sorted', 'str', 'sum', 'tuple', 'zip', 'complex', 'bin', 'hex', 'repr', 'type', 'ValueError', 'ZeroDivisionError', 'TypeError', 'IndexError', 'KeyError', 'Exception',
)


def run_python(ctx: Ctx, src: str) -> None:
    def _print(*args: Any, sep: str = ' ', end: str = '\n', **_: Any) -> None:
        ctx.disp.append(sep.join(str(a) for a in args))

    def _input(prompt: Any = '') -> str:
        return read_input(ctx, str(prompt), 'str')

    allowed = {'math': math, 'random': random, 'sympy': sp, 'cmath': __import__('cmath'), 'fractions': __import__('fractions'), 'statistics': __import__('statistics'), 'time': __import__('time')}

    def _import(name: str, globals_: Any = None, locals_: Any = None, fromlist: Any = (), level: int = 0) -> Any:
        if name in allowed:
            return allowed[name]
        raise ImportError(f'module {name} is not available')

    safe: Dict[str, Any] = {k: getattr(builtins, k) for k in SAFE_NAMES}
    safe.update({'print': _print, 'input': _input, '__import__': _import, '__build_class__': builtins.__build_class__, '__name__': '__main__'})
    env: Dict[str, Any] = {'__builtins__': safe, '__name__': '__main__'}
    try:
        code = compile(src, '<script>', 'exec')
    except SyntaxError as exc:
        raise TIError(f'Syntax error line {exc.lineno}: {exc.msg}')
    old = sys.gettrace()
    sys.settrace(_Limit(2000000))
    try:
        exec(code, env)
    except (NeedInput, TIError):
        raise
    except Exception as exc:
        tb = exc.__traceback__
        line = 0
        while tb is not None:
            if tb.tb_frame.f_code.co_filename == '<script>':
                line = tb.tb_lineno
            tb = tb.tb_next
        raise TIError(f'{type(exc).__name__} line {line}: {exc}')
    finally:
        sys.settrace(old)

