"""Algebra and complex-number commands."""
from typing import Any, Dict, List, Optional, Sequence

import sympy as sp
from sympy.simplify.fu import TR5, TR7, TR8

from .cmd_math import as_list, num
from .core import Ctx, func, is_bool, is_mat, map_value, need_expr, sym
from .parser import TIError
from .values import TList

REL = sp.core.relational.Relational
TRIG = (sp.sin, sp.cos, sp.tan, sp.sec, sp.csc, sp.cot)


def as_zero(e: Any) -> Any:
    if isinstance(e, sp.Equality):
        return e.lhs - e.rhs
    if e is sp.true:
        return sp.Integer(0)
    if e is sp.false:
        return sp.Integer(1)
    if is_bool(e):
        raise TIError('Argument: equation or expression expected')
    return need_expr(e)


def split_vars(args: Sequence[Any]) -> List[Any]:
    out: List[Any] = []
    for a in args:
        if isinstance(a, TList):
            out.extend(split_vars(a))
        elif isinstance(a, sp.Symbol):
            out.append((a, None))
        elif isinstance(a, sp.Equality) and isinstance(a.lhs, sp.Symbol):
            out.append((a.lhs, a.rhs))
        else:
            raise TIError('Argument: variable expected')
    if not out:
        raise TIError('Argument: variable expected')
    return out


def numeric_roots(expr: Any, x: sp.Symbol, lo: float, hi: float, samples: int = 400) -> List[Any]:
    try:
        f = sp.lambdify(x, expr, modules=['mpmath'])
    except Exception:
        return []
    import mpmath as mp

    def val(t: float) -> Optional[float]:
        try:
            v = complex(f(t))
            return v.real if abs(v.imag) < 1e-12 and v.real == v.real else None
        except Exception:
            return None

    roots: List[float] = []
    step = (hi - lo) / samples
    prev_t, prev_v = lo, val(lo)
    for k in range(1, samples + 1):
        t = lo + k * step
        v = val(t)
        if prev_v is not None and v is not None:
            if prev_v == 0:
                roots.append(prev_t)
            elif prev_v * v < 0:
                try:
                    r = float(mp.findroot(f, (prev_t, t), solver='anderson', tol=1e-13, maxsteps=80).real)
                    if prev_t - 1e-9 <= r <= t + 1e-9:
                        roots.append(r)
                except Exception:
                    pass
        prev_t, prev_v = t, v
    if prev_v == 0:
        roots.append(prev_t)
    out: List[float] = []
    for r in roots:
        if not any(abs(r - q) < 1e-9 * max(1.0, abs(r)) for q in out):
            out.append(r)
    return [sp.Float(r, 15) for r in out]


def sort_solutions(sols: Sequence[Any]) -> List[Any]:
    uniq: List[Any] = []
    for s in sols:
        if not any(s == u for u in uniq):
            uniq.append(s)
    try:
        return sorted(uniq, key=lambda s: (float(sp.re(sp.N(s))), float(sp.im(sp.N(s)))))
    except (TypeError, ValueError):
        return uniq


def general_solutions(sset: Any, x: sp.Symbol, counter: List[int]) -> Optional[List[Any]]:
    if sset is sp.S.EmptySet:
        return []
    if isinstance(sset, sp.FiniteSet):
        return list(sset)
    if isinstance(sset, sp.Union):
        out: List[Any] = []
        for part in sset.args:
            sub = general_solutions(part, x, counter)
            if sub is None:
                return None
            out.extend(sub)
        return out
    if isinstance(sset, sp.ImageSet) and sset.base_sets == (sp.S.Integers,):
        counter[0] += 1
        n = sp.Symbol(f'n{counter[0]}', integer=True)
        lam = sset.lamda
        return [sp.expand(lam.expr.subs(lam.variables[0], n))]
    return None


def solve_one(ctx: Ctx, expr: Any, x: sp.Symbol, complex_mode: bool = False) -> Optional[List[Any]]:
    """Return a list of solutions, or None when every value is a solution."""
    expr = sp.together(expr) if expr.is_rational_function(x) else expr
    if x not in expr.free_symbols:
        return None if sp.simplify(expr) == 0 else []
    if complex_mode:
        z = sp.Symbol(x.name)
        try:
            sols = sp.solve(expr.xreplace({x: z}), z)
        except NotImplementedError:
            sols = []
        return sort_solutions([sp.simplify(s) if sp.count_ops(s) < 80 else s for s in sols])
    domain = ctx.domain.get(x)
    floaty = bool(expr.atoms(sp.Float))
    if domain is not None:
        try:
            sset = sp.solveset(expr, x, domain)
            if isinstance(sset, sp.FiniteSet):
                return sort_solutions(list(sset))
            if sset is sp.S.EmptySet:
                return []
            if sset == domain:
                return None
        except Exception:
            pass
        try:
            lo = float(domain.inf) if domain.inf.is_finite else -100.0
            hi = float(domain.sup) if domain.sup.is_finite else 100.0
        except (TypeError, AttributeError):
            lo, hi = -100.0, 100.0
        cands: List[Any] = []
        try:
            cands = [s for s in sp.solve(expr, x) if s.is_real and domain.contains(s) == sp.true]
        except Exception:
            cands = []
        nums = numeric_roots(expr, x, lo, hi)
        nums = [r for r in nums if domain.contains(r) != sp.false and not any(abs(float(r) - float(sp.N(c))) < 1e-8 for c in cands)]
        return sort_solutions(cands + nums)
    try:
        if expr.has(*TRIG) and not floaty:
            sset = sp.solveset(expr, x, sp.S.Reals)
            gen = general_solutions(sset, x, [0])
            if gen is not None:
                return sort_solutions(gen) if all(not s.free_symbols - expr.free_symbols for s in gen) else gen
        sols = sp.solve(expr, x)
        real = [s for s in sols if s.is_real is not False and not s.has(sp.I)]
        if sols or expr.is_polynomial(x):
            return sort_solutions(real)
    except (NotImplementedError, ValueError, TypeError):
        pass
    return sort_solutions(numeric_roots(expr, x, -100.0, 100.0, 2000))


def solutions_to_bool(x: sp.Symbol, sols: Optional[List[Any]]) -> Any:
    if sols is None:
        return sp.true
    if not sols:
        return sp.false
    eqs = [sp.Eq(x, s, evaluate=False) for s in sols]
    return eqs[0] if len(eqs) == 1 else sp.Or(*eqs, evaluate=False)


def clean_relational(b: Any) -> Any:
    if isinstance(b, REL):
        if b.lhs in (sp.oo, -sp.oo) or b.rhs in (sp.oo, -sp.oo):
            return sp.true
        return b.canonical
    if isinstance(b, (sp.And, sp.Or)):
        parts = [clean_relational(a) for a in b.args]
        if isinstance(b, sp.And):
            parts = [sp.Le(p.rhs, p.lhs, evaluate=False) if isinstance(p, sp.Ge) else sp.Lt(p.rhs, p.lhs, evaluate=False) if isinstance(p, sp.Gt) else p for p in parts]
            parts = [p for p in parts if p is not sp.true]
            return parts[0] if len(parts) == 1 else sp.And(*parts, evaluate=False)
        return b.func(*parts)
    return b


def system_parts(eq: Any) -> List[Any]:
    if isinstance(eq, sp.And):
        out: List[Any] = []
        for a in eq.args:
            out.extend(system_parts(a))
        return out
    if isinstance(eq, TList):
        out = []
        for a in eq:
            out.extend(system_parts(a))
        return out
    return [eq]


def solve_general(ctx: Ctx, eq: Any, vars_: Sequence[Any], complex_mode: bool) -> Any:
    pairs = split_vars(vars_)
    syms = [p[0] for p in pairs]
    parts = system_parts(eq)
    if len(parts) == 1 and len(syms) == 1:
        e, x = parts[0], syms[0]
        if isinstance(e, REL) and not isinstance(e, (sp.Equality, sp.Unequality)):
            try:
                out = sp.solve_univariate_inequality(e, x, relational=True, domain=ctx.domain.get(x, sp.S.Reals))
                return clean_relational(out)
            except Exception:
                raise TIError('Unable to solve inequality')
        return solutions_to_bool(x, solve_one(ctx, as_zero(e), x, complex_mode))
    exprs = [as_zero(p) for p in parts]
    mapping: Dict[sp.Symbol, sp.Symbol] = {s: sp.Symbol(s.name) for s in syms} if complex_mode else {}
    try:
        res = sp.solve([e.xreplace(mapping) for e in exprs], [mapping.get(s, s) for s in syms], dict=True)
    except NotImplementedError:
        res = []
    if not res and any(p[1] is not None for p in pairs) or (not res and not all(e.is_polynomial(*syms) for e in exprs)):
        try:
            guess = [num(p[1]) if p[1] is not None else 1.0 for p in pairs]
            sol = sp.nsolve(exprs, syms, guess)
            res = [{s: sp.Float(v, 15) for s, v in zip(syms, sol)}]
        except Exception:
            res = []
    back = {v: k for k, v in mapping.items()}
    rows = []
    for r in res:
        r = {back.get(k, k): v.xreplace(back) for k, v in r.items()}
        if not complex_mode and any(v.is_real is False or v.has(sp.I) for v in r.values()):
            continue
        counter = 0
        eqs = []
        for s in syms:
            if s in r:
                eqs.append(sp.Eq(s, sp.simplify(r[s]), evaluate=False))
            else:
                counter += 1
                c = sp.Symbol(f'c{counter}', real=True)
                for k in list(r):
                    r[k] = r[k].subs(s, c)
                eqs.append(sp.Eq(s, c, evaluate=False))
        eqs = [sp.Eq(e.lhs, r.get(e.lhs, e.rhs), evaluate=False) for e in eqs]
        rows.append(eqs[0] if len(eqs) == 1 else sp.And(*eqs, evaluate=False))
    if not rows:
        return sp.false
    return rows[0] if len(rows) == 1 else sp.Or(*rows, evaluate=False)


@func('solve', bind_rest=True)
def f_solve(ctx: Ctx, eq: Any, *vars_: Any) -> Any:
    return solve_general(ctx, eq, vars_, False)


@func('csolve', bind_rest=True)
def f_csolve(ctx: Ctx, eq: Any, *vars_: Any) -> Any:
    return solve_general(ctx, eq, vars_, True)


@func('zeros', bind_rest=True)
def f_zeros(ctx: Ctx, e: Any, var: Any) -> Any:
    x = split_vars([var])[0][0]
    sols = solve_one(ctx, as_zero(e), x)
    if sols is None:
        raise TIError('Every value is a zero')
    return TList(sols)


@func('czeros', bind_rest=True)
def f_czeros(ctx: Ctx, e: Any, var: Any) -> Any:
    x = split_vars([var])[0][0]
    return TList(solve_one(ctx, as_zero(e), x, True) or [])


@func('nsolve', bind_rest=True)
def f_nsolve(ctx: Ctx, eq: Any, var: Any, lo: Any = None, hi: Any = None) -> Any:
    x, guess = split_vars([var])[0]
    expr = as_zero(eq)
    if lo is not None and hi is not None:
        roots = numeric_roots(expr, x, num(lo), num(hi), 800)
        return roots[0] if roots else sp.false
    dom = ctx.domain.get(x)
    if dom is not None and guess is None:
        try:
            roots = numeric_roots(expr, x, float(dom.inf) if dom.inf.is_finite else -100.0, float(dom.sup) if dom.sup.is_finite else 100.0, 800)
            if roots:
                return roots[0]
        except (TypeError, AttributeError):
            pass
    for g in ([num(guess)] if guess is not None else [0.5, 1.0, -1.0, 3.0, -3.0, 10.0, -10.0, 0.01]):
        try:
            r = sp.nsolve(expr, x, g)
            if abs(sp.im(r)) < 1e-12:
                return sp.Float(sp.re(r), 15)
        except Exception:
            continue
    roots = numeric_roots(expr, x, -100.0, 100.0, 2000)
    return min(roots, key=lambda r: abs(float(r))) if roots else sp.false


@func('linsolve', bind_rest=True)
def f_linsolve(ctx: Ctx, eqs: Any, *vars_: Any) -> Any:
    syms = [p[0] for p in split_vars(vars_)]
    exprs = [as_zero(p) for p in system_parts(eqs)]
    try:
        res = sp.linsolve(exprs, syms)
    except Exception:
        raise TIError('Argument: linear system expected')
    if res is sp.S.EmptySet or not res:
        raise TIError('No solution found')
    sol = list(res)[0]
    taus = sorted(set().union(*[s.free_symbols for s in sol]) & set(syms), key=lambda s: s.name)
    repl = {t: sp.Symbol(f'c{i + 1}', real=True) for i, t in enumerate(taus)}
    return TList(sp.simplify(s.xreplace(repl)) for s in sol)


def real_factor(expr: Any, x: sp.Symbol, complex_mode: bool) -> Any:
    num_, den = sp.fraction(sp.together(expr))

    def fac(p: Any) -> Any:
        if not p.is_polynomial(x) or sp.degree(p, x) < 1:
            return sp.factor(p)
        poly = sp.Poly(p, x)
        try:
            roots = sp.roots(poly)
        except Exception:
            roots = {}
        if sum(roots.values()) != poly.degree():
            return sp.factor(p, gaussian=True) if complex_mode else sp.factor(p)
        out = poly.LC()
        rest = sp.Integer(1)
        done: List[Any] = []
        for r, m in sorted(roots.items(), key=lambda kv: sp.default_sort_key(kv[0])):
            if r in done:
                continue
            if complex_mode or r.is_real:
                out = out * (x - r) ** m
            else:
                c = sp.conjugate(r)
                done.append(c)
                rest = rest * sp.expand((x - r) * (x - c)) ** m
        return out * rest

    return fac(num_) / fac(den) if den != 1 else fac(num_)


@func('factor', bind=(1,))
def f_factor(ctx: Ctx, e: Any, var: Any = None) -> Any:
    def one(v: Any) -> Any:
        if isinstance(v, REL):
            return v.func(one(v.lhs), one(v.rhs))
        if v.is_Integer:
            if abs(v) < 2:
                return v
            f = sp.factorint(abs(int(v)))
            terms = [sp.Pow(p, k, evaluate=False) if k > 1 else sp.Integer(p) for p, k in sorted(f.items())]
            if v < 0:
                terms.insert(0, sp.Integer(-1))
            return terms[0] if len(terms) == 1 else sp.Mul(*terms, evaluate=False)
        if v.is_Rational:
            return sp.Mul(one(v.p), sp.Pow(one(sp.Integer(v.q)), -1, evaluate=False), evaluate=False)
        if isinstance(var, sp.Symbol):
            return real_factor(v, var, False)
        return sp.factor(v)

    return map_value(one, e)


@func('cfactor', bind=(1,))
def f_cfactor(ctx: Ctx, e: Any, var: Any = None) -> Any:
    return map_value(lambda v: real_factor(v, var, True) if isinstance(var, sp.Symbol) else sp.factor(v, gaussian=True), e)


def partial_fractions(v: Any, x: Optional[sp.Symbol]) -> Any:
    out = sp.expand(v)
    n, d = sp.fraction(sp.together(v))
    syms = sorted(d.free_symbols, key=lambda s: s.name)
    if not syms:
        return out
    target = x if x is not None and x in d.free_symbols else syms[0]
    try:
        if n.is_polynomial(target) and d.is_polynomial(target):
            return sp.apart(sp.together(v), target)
    except Exception:
        pass
    return out


@func('expand', bind=(1,))
def f_expand(ctx: Ctx, e: Any, var: Any = None) -> Any:
    def one(v: Any) -> Any:
        if isinstance(v, REL):
            return v.func(one(v.lhs), one(v.rhs))
        return partial_fractions(sp.expand_log(v, force=False), var if isinstance(var, sp.Symbol) else None)

    return map_value(one, e)


@func('partfrac', bind=(1,))
def f_partfrac(ctx: Ctx, e: Any, var: Any = None) -> Any:
    return map_value(lambda v: partial_fractions(v, var if isinstance(var, sp.Symbol) else None), e)


@func('propfrac', bind=(1,))
def f_propfrac(ctx: Ctx, e: Any, var: Any = None) -> Any:
    def one(v: Any) -> Any:
        if v.is_Rational:
            if v.is_Integer or abs(v) < 1:
                return v
            whole = sp.Integer(int(v))
            return sp.Add(whole, v - whole, evaluate=False)
        n, d = sp.fraction(sp.together(v))
        syms = sorted(d.free_symbols, key=lambda s: s.name)
        x = var if isinstance(var, sp.Symbol) else (syms[0] if syms else None)
        if x is None or not (n.is_polynomial(x) and d.is_polynomial(x)):
            return v
        q, r = sp.div(sp.expand(n), sp.expand(d), x)
        return q + r / d

    return map_value(one, e)


@func('comdenom', bind=(1,))
def f_comdenom(ctx: Ctx, e: Any, var: Any = None) -> Any:
    def one(v: Any) -> Any:
        n, d = sp.fraction(sp.cancel(sp.together(v)))
        if isinstance(var, sp.Symbol):
            return sp.collect(sp.expand(n), var) / sp.collect(sp.expand(d), var)
        return sp.expand(n) / sp.expand(d)

    return map_value(one, e)


@func('completesquare', bind_rest=True)
def f_completesquare(ctx: Ctx, e: Any, *vars_: Any) -> Any:
    syms = [p[0] for p in split_vars(vars_)]

    def complete(expr: Any) -> Any:
        out = sp.expand(expr)
        squares = sp.Integer(0)
        for x in syms:
            p = sp.Poly(out, x)
            if p.degree() != 2:
                raise TIError('Argument: quadratic expected')
            a, b, c = p.all_coeffs()
            squares = squares + a * (x + b / (2 * a)) ** 2
            out = sp.expand(c - b ** 2 / (4 * a))
        return squares, out

    if isinstance(e, sp.Equality):
        sq, rest = complete(e.lhs - e.rhs)
        return sp.Eq(sq, -rest, evaluate=False)
    sq, rest = complete(need_expr(e))
    return sq + rest


@func('texpand')
def f_texpand(ctx: Ctx, e: Any) -> Any:
    return map_value(lambda v: sp.expand_trig(v), e)


@func('tcollect')
def f_tcollect(ctx: Ctx, e: Any) -> Any:
    return map_value(lambda v: sp.expand(TR8(sp.expand(TR7(TR5(v))))), e)


def poly_of(e: Any, var: Any) -> Any:
    expr = as_zero(e)
    if isinstance(var, sp.Symbol):
        x = var
    else:
        syms = sorted(expr.free_symbols, key=lambda s: s.name)
        x = sym('x') if sym('x') in syms or not syms else syms[0]
    try:
        return sp.Poly(sp.expand(expr), x), x
    except sp.PolynomialError:
        raise TIError('Argument: polynomial expected')


def poly_roots(e: Any, var: Any, complex_mode: bool) -> Any:
    if isinstance(e, TList):
        x = sp.Symbol('x', real=True)
        poly = sp.Poly(list(e), x)
    else:
        poly, x = poly_of(e, var)
    try:
        roots = sp.roots(poly, multiple=True)
    except Exception:
        roots = []
    if len(roots) != poly.degree():
        roots = [sp.N(r, 15) for r in poly.nroots(n=15)]
    if not complex_mode:
        roots = [r for r in roots if r.is_real or abs(sp.im(sp.N(r))) < 1e-12]
    return TList(sort_solutions(roots))


func('polyroots', bind=(1,))(lambda ctx, e, var=None: poly_roots(e, var, False))
func('cpolyroots', bind=(1,))(lambda ctx, e, var=None: poly_roots(e, var, True))


@func('polycoeffs', bind=(1,))
def f_polycoeffs(ctx: Ctx, e: Any, var: Any = None) -> Any:
    return TList(poly_of(e, var)[0].all_coeffs())


@func('polydegree', bind=(1,))
def f_polydegree(ctx: Ctx, e: Any, var: Any = None) -> Any:
    return sp.Integer(poly_of(e, var)[0].degree())


@func('polyeval')
def f_polyeval(ctx: Ctx, coeffs: Any, x: Any) -> Any:
    out = sp.Integer(0)
    for c in as_list(coeffs):
        out = out * x + c
    return sp.expand(out) if isinstance(out, sp.Expr) else out


def _divide(a: Any, b: Any, var: Any) -> Any:
    x = var if isinstance(var, sp.Symbol) else poly_of(a, None)[1]
    return sp.div(sp.expand(need_expr(a)), sp.expand(need_expr(b)), x)


func('polyquotient', 'quotient', bind=(2,))(lambda ctx, a, b, var=None: _divide(a, b, var)[0])
func('polyremainder', 'remainder', bind=(2,))(lambda ctx, a, b, var=None: _divide(a, b, var)[1])
func('polygcd')(lambda ctx, a, b: sp.gcd(need_expr(a), need_expr(b)))


@func('rect')
def f_rect(ctx: Ctx, e: Any) -> Any:
    return map_value(lambda v: sp.expand_complex(v), e)


@func('polar')
def f_polar(ctx: Ctx, e: Any) -> Any:
    from .core import convert

    return convert(ctx, 'polar', e, [])


@func('simplify')
def f_simplify(ctx: Ctx, e: Any) -> Any:
    return map_value(lambda v: sp.simplify(v) if isinstance(v, sp.Basic) else v, e)

sources.cmd_calculus.py:
"""Calculus, series and differential-equation commands."""
from typing import Any, List, Optional

import sympy as sp

from .cmd_algebra import as_zero, numeric_roots, solve_one, sort_solutions, system_parts
from .cmd_math import integer, num
from .core import Ctx, ev, func, map_value, need_expr, sym, tidy
from .parser import Node, TIError
from .values import TList

REL = sp.core.relational.Relational


def var_of(v: Any) -> sp.Symbol:
    if not isinstance(v, sp.Symbol):
        raise TIError('Argument: variable expected')
    return v


def neat(e: Any) -> Any:
    try:
        if isinstance(e, sp.Expr) and sp.count_ops(e) < 120:
            s = sp.simplify(e)
            return s if sp.count_ops(s) <= sp.count_ops(e) else e
    except Exception:
        pass
    return e


@func('d', 'derivative', bind=(1,))
def f_d(ctx: Ctx, e: Any, var: Any, order: Any = sp.Integer(1)) -> Any:
    x, n = var_of(var), integer(order)

    def one(v: Any) -> Any:
        if isinstance(v, REL):
            return v.func(one(v.lhs), one(v.rhs))
        if n < 0:
            out = v
            for _ in range(-n):
                out = sp.integrate(out, x)
            return out
        return tidy(sp.diff(v, x, n))

    return map_value(one, e)


@func('∫', 'integral', 'integrate', bind=(1,))
def f_int(ctx: Ctx, e: Any, var: Any, lo: Any = None, hi: Any = None) -> Any:
    x = var_of(var)

    def one(v: Any) -> Any:
        if lo is None or hi is None:
            out = sp.integrate(v, x)
            if out.has(sp.Integral):
                return out
            out = out + (need_expr(lo) if lo is not None else 0)
            return neat(out.rewrite(sp.Piecewise) if out.has(sp.Heaviside) else out)
        try:
            out = sp.integrate(v, (x, lo, hi))
        except Exception:
            out = sp.Integral(v, (x, lo, hi))
        if out.has(sp.Integral) or out is sp.nan:
            try:
                return sp.Float(sp.Integral(v, (x, lo, hi)).evalf(15), 15)
            except Exception:
                return sp.Integral(v, (x, lo, hi))
        return neat(out)

    return map_value(one, e)


@func('nint', bind=(1,))
def f_nint(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any) -> Any:
    try:
        return sp.Float(sp.Integral(need_expr(e), (var_of(var), lo, hi)).evalf(15), 15)
    except Exception:
        raise TIError('Unable to evaluate numerically')


@func('lim', 'limit', bind=(1,))
def f_lim(ctx: Ctx, e: Any, var: Any, point: Any, direction: Any = sp.Integer(0)) -> Any:
    x, d = var_of(var), num(direction)

    def one(v: Any) -> Any:
        try:
            if d > 0 or point is -sp.oo:
                return sp.limit(v, x, point, '+')
            if d < 0 or point is sp.oo:
                return sp.limit(v, x, point, '-')
            left, right = sp.limit(v, x, point, '-'), sp.limit(v, x, point, '+')
        except Exception:
            return sp.Limit(v, x, point)
        return right if sp.simplify(left - right) == 0 else sp.nan

    return map_value(one, e)


@func('Σ', 'sumseq', bind=(1,))
def f_sigma(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any) -> Any:
    k = sp.Symbol(var_of(var).name, integer=True)
    return map_value(lambda v: neat(sp.summation(v.xreplace({var: k}), (k, lo, hi)).xreplace({k: var})), e)


@func('Π', 'prodseq', bind=(1,))
def f_pi(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any) -> Any:
    k = sp.Symbol(var_of(var).name, integer=True)
    return map_value(lambda v: neat(sp.product(v.xreplace({var: k}), (k, lo, hi)).xreplace({k: var})), e)


def extremum(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any, sign: int, numeric: bool) -> Any:
    x = var_of(var)
    f = need_expr(e)
    dom = ctx.domain.get(x)
    a = lo if lo is not None else (dom.inf if dom is not None else -sp.oo)
    b = hi if hi is not None else (dom.sup if dom is not None else sp.oo)
    saved = ctx.domain.get(x)
    if a.is_finite or b.is_finite:
        ctx.domain[x] = sp.Interval(a, b)
    try:
        crit = solve_one(ctx, sp.diff(f, x), x) or []
    finally:
        if saved is None:
            ctx.domain.pop(x, None)
        else:
            ctx.domain[x] = saved
    cands: List[Any] = []
    for c in crit:
        try:
            if c.is_number and (c < a) != sp.true and (c > b) != sp.true:
                cands.append((c, f.subs(x, c)))
        except TypeError:
            continue
    for end in (a, b):
        try:
            cands.append((end, f.subs(x, end) if end.is_finite else sp.limit(f, x, end)))
        except Exception:
            continue
    best: Optional[float] = None
    picks: List[Any] = []
    for c, val in cands:
        try:
            fv = float(sp.N(val)) * sign
        except (TypeError, ValueError):
            continue
        if fv != fv:
            continue
        if best is None or fv < best - 1e-12:
            best, picks = fv, [c]
        elif abs(fv - best) <= 1e-12:
            picks.append(c)
    if not picks:
        raise TIError('Unable to find extremum')
    picks = sort_solutions(picks)
    eqs = [sp.Eq(x, sp.Float(sp.N(p), 15) if numeric and p.is_finite else p, evaluate=False) for p in picks]
    return eqs[0] if len(eqs) == 1 else sp.Or(*eqs, evaluate=False)


func('fmin', bind=(1,))(lambda ctx, e, var, lo=None, hi=None: extremum(ctx, e, var, lo, hi, 1, False))
func('fmax', bind=(1,))(lambda ctx, e, var, lo=None, hi=None: extremum(ctx, e, var, lo, hi, -1, False))
func('nfmin', bind=(1,))(lambda ctx, e, var, lo=None, hi=None: extremum(ctx, e, var, lo, hi, 1, True).rhs)
func('nfmax', bind=(1,))(lambda ctx, e, var, lo=None, hi=None: extremum(ctx, e, var, lo, hi, -1, True).rhs)


def var_point(var: Any, point: Any) -> Any:
    if isinstance(var, sp.Equality) and isinstance(var.lhs, sp.Symbol):
        return var.lhs, var.rhs
    if point is None:
        raise TIError('Argument: point expected')
    return var_of(var), point


@func('tangentline', bind=(1,))
def f_tangent(ctx: Ctx, e: Any, var: Any, point: Any = None) -> Any:
    x, a = var_point(var, point)
    f = need_expr(e)
    slope = sp.diff(f, x).subs(x, a)
    if not slope.is_finite:
        return sp.Eq(x, a, evaluate=False)
    return sp.expand(f.subs(x, a) + slope * (x - a))


@func('normalline', bind=(1,))
def f_normal(ctx: Ctx, e: Any, var: Any, point: Any = None) -> Any:
    x, a = var_point(var, point)
    f = need_expr(e)
    slope = sp.diff(f, x).subs(x, a)
    if slope == 0:
        return sp.Eq(x, a, evaluate=False)
    return sp.expand(f.subs(x, a) - (x - a) / slope)


@func('arclen', bind=(1,))
def f_arclen(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any) -> Any:
    x = var_of(var)
    integrand = sp.sqrt(1 + sp.diff(need_expr(e), x) ** 2)
    return f_int(ctx, sp.simplify(integrand), x, lo, hi)


@func('taylor', 'series', bind=(1,))
def f_taylor(ctx: Ctx, e: Any, var: Any, order: Any, point: Any = sp.Integer(0)) -> Any:
    x = var_of(var)
    try:
        return sp.series(need_expr(e), x, point, integer(order) + 1).removeO()
    except Exception:
        raise TIError('Unable to compute series')


@func('nderivative', bind=(1,))
def f_nderiv(ctx: Ctx, e: Any, var: Any, order: Any = sp.Integer(1)) -> Any:
    x, a = var_point(var, None) if isinstance(var, sp.Equality) else (var_of(var), None)
    out = sp.diff(need_expr(e), x, integer(order))
    return sp.Float(sp.N(out.subs(x, a)), 15) if a is not None else out


@func('avgrc', bind=(1,))
def f_avgrc(ctx: Ctx, e: Any, var: Any, step: Any = sp.Rational(1, 1000)) -> Any:
    x, a = (var.lhs, var.rhs) if isinstance(var, sp.Equality) else (var_of(var), None)
    f = need_expr(e)
    out = (f.subs(x, x + step) - f) / step
    return out.subs(x, a) if a is not None else sp.simplify(out)


@func('impdif', bind=(1, 2))
def f_impdif(ctx: Ctx, eq: Any, var: Any, dep: Any, order: Any = sp.Integer(1)) -> Any:
    try:
        return sp.simplify(sp.idiff(as_zero(eq), var_of(dep), var_of(var), integer(order)))
    except Exception:
        raise TIError('Unable to differentiate implicitly')


@func('desolve', raw=True)
def f_desolve(ctx: Ctx, ode: Node, var: Node, dep: Node) -> Any:
    if var[0] != 'name' or dep[0] != 'name':
        raise TIError('Argument: deSolve(ODE, Var, depVar)')
    x = sym(var[1])
    yname = dep[1].lower()
    yf = sp.Function(yname)(x)
    ctx.shield.append({x.name})
    saved, ctx.de = ctx.de, (yname, x, yf)
    try:
        parts = system_parts(ev(ctx, ode))
    finally:
        ctx.de = saved
        ctx.shield.pop()
    eqs: List[Any] = []
    ics = {}
    for p in parts:
        if not isinstance(p, sp.Equality):
            raise TIError('Argument: equation expected')
        lhs = p.lhs
        if isinstance(lhs, sp.Subs) or (getattr(lhs, 'func', None) == yf.func and x not in lhs.free_symbols):
            ics[lhs] = p.rhs
        else:
            eqs.append(p)
    if len(eqs) != 1:
        raise TIError('Argument: one differential equation expected')
    try:
        sol = sp.dsolve(eqs[0], yf, ics=ics or None)
    except Exception:
        try:
            sol = sp.dsolve(eqs[0], yf)
            if isinstance(sol, list):
                sol = sol[0]
            if ics:
                consts = sorted(sol.free_symbols - eqs[0].free_symbols - {x}, key=lambda s: s.name)
                conds = []
                for k, v in ics.items():
                    if isinstance(k, sp.Subs):
                        conds.append(sp.Eq(sp.diff(sol.rhs, *k.expr.variable_count).subs(x, k.point[0]), v))
                    else:
                        conds.append(sp.Eq(sol.rhs.subs(x, k.args[0]), v))
                found = sp.solve(conds, consts, dict=True)
                if found:
                    sol = sol.subs(found[0])
        except Exception:
            raise TIError('Unable to solve differential equation')
    if isinstance(sol, list):
        sol = sol[0]
    y = sym(yname)
    out = sol.xreplace({yf: y}) if isinstance(sol, sp.Equality) else sol
    consts = sorted([s for s in out.free_symbols if s.name.startswith('C') and s.name[1:].isdigit()], key=lambda s: s.name)
    out = out.xreplace({c: sp.Symbol(f'c{c.name[1:]}', real=True) for c in consts})
    if isinstance(out, sp.Equality):
        return sp.Eq(out.lhs, neat(out.rhs), evaluate=False)
    return out


def stepper(ctx: Ctx, e: Any, var: Any, dep: Any, span: Any, y0: Any, step: Any, method: str) -> Any:
    x, y = var_of(var), var_of(dep)
    if not isinstance(span, TList) or len(span) != 2:
        raise TIError('Argument: {Var0, VarMax} expected')
    f = sp.lambdify((x, y), need_expr(e), modules=['math'])
    t, tmax, h, v = num(span[0]), num(span[1]), num(step), num(y0)
    if h <= 0 or (tmax - t) / h > 5000:
        raise TIError('Domain: invalid step')
    xs, ys = [t], [v]
    while t < tmax - 1e-12:
        if method == 'euler':
            v = v + h * f(t, v)
        else:
            k1 = f(t, v)
            k2 = f(t + h / 2, v + h * k1 / 2)
            k3 = f(t + h / 2, v + h * k2 / 2)
            k4 = f(t + h, v + h * k3)
            v = v + h * (k1 + 2 * k2 + 2 * k3 + k4) / 6
        t = t + h
        xs.append(t)
        ys.append(v)
    return sp.ImmutableMatrix([[sp.Float(a, 15) for a in xs], [sp.Float(b, 15) for b in ys]])


func('euler', bind=(1, 2))(lambda ctx, e, var, dep, span, y0, step: stepper(ctx, e, var, dep, span, y0, step, 'euler'))
func('rk23', 'rk4', bind=(1, 2))(lambda ctx, e, var, dep, span, y0, step: stepper(ctx, e, var, dep, span, y0, step, 'rk'))

sources.cmd_math.py:
"""Number, elementary, list and string functions plus core commands."""
import random
from typing import Any, List

import sympy as sp

from .core import Ctx, as_expr, approx_value, command, ev, func, is_bool, is_mat, map_value, need_expr, sym, to_bool
from .parser import Node, TIError, parse_expr
from .printer import to_text
from .values import Control, TList, TStr, UFunc

RNG = random.Random()


def rad(ctx: Ctx, x: Any) -> Any:
    return x * sp.pi / 180 if ctx.deg else x


def deg(ctx: Ctx, x: Any) -> Any:
    return x * 180 / sp.pi if ctx.deg else x


def num(v: Any, what: str = 'number') -> float:
    try:
        return float(sp.N(v))
    except (TypeError, ValueError):
        raise TIError(f'Data type: {what} expected')


def integer(v: Any, what: str = 'integer') -> int:
    f = num(v, what)
    if abs(f - round(f)) > 1e-9:
        raise TIError(f'Domain: {what} expected')
    return int(round(f))


def as_list(v: Any, what: str = 'list') -> TList:
    if isinstance(v, TList):
        return v
    if is_mat(v) and (v.rows == 1 or v.cols == 1):
        return TList(list(v))
    raise TIError(f'Data type: {what} expected')


def _reg(names: Any, fn: Any) -> None:
    func(*names, listable=True)(fn)


for _names, _f in (
    (('sin',), sp.sin), (('cos',), sp.cos), (('tan',), sp.tan), (('sec',), sp.sec), (('csc',), sp.csc), (('cot',), sp.cot),
):
    _reg(_names, lambda ctx, x, _f=_f: _f(rad(ctx, need_expr(x))))
for _names, _f in (
    (('sin⁻¹', 'arcsin', 'asin'), sp.asin), (('cos⁻¹', 'arccos', 'acos'), sp.acos), (('tan⁻¹', 'arctan', 'atan'), sp.atan),
    (('sec⁻¹', 'arcsec'), sp.asec), (('csc⁻¹', 'arccsc'), sp.acsc), (('cot⁻¹', 'arccot'), sp.acot),
):
    _reg(_names, lambda ctx, x, _f=_f: deg(ctx, _f(need_expr(x))))
for _names, _f in (
    (('sinh',), sp.sinh), (('cosh',), sp.cosh), (('tanh',), sp.tanh), (('sinh⁻¹', 'arcsinh'), sp.asinh), (('cosh⁻¹', 'arccosh'), sp.acosh), (('tanh⁻¹', 'arctanh'), sp.atanh),
    (('ln',), sp.log), (('exp',), sp.exp), (('sqrt',), sp.sqrt), (('abs',), sp.Abs), (('sign', 'signum'), sp.sign), (('floor', 'int'), sp.floor), (('ceiling',), sp.ceiling),
    (('real',), sp.re), (('imag',), sp.im), (('conj',), sp.conjugate),
):
    _reg(_names, lambda ctx, x, _f=_f: _f(need_expr(x)))


@func('abs')
def f_abs(ctx: Ctx, x: Any) -> Any:
    if is_mat(x):
        return sp.ImmutableMatrix(x.applyfunc(sp.Abs))
    return map_value(sp.Abs, x)


@func('log', listable=True)
def f_log(ctx: Ctx, x: Any, base: Any = sp.Integer(10)) -> Any:
    return sp.log(need_expr(x), need_expr(base))


@func('root', listable=True)
def f_root(ctx: Ctx, x: Any, n: Any = sp.Integer(2)) -> Any:
    if x.is_number and n.is_Integer and x.is_real and x < 0 and n % 2 == 1:
        return -sp.Pow(-x, sp.Rational(1, int(n)))
    return sp.Pow(x, 1 / n)


@func('angle', listable=True)
def f_angle(ctx: Ctx, x: Any) -> Any:
    return deg(ctx, sp.arg(need_expr(x)))


@func('ipart', listable=True)
def f_ipart(ctx: Ctx, x: Any) -> Any:
    return sp.sign(x) * sp.floor(sp.Abs(x))


@func('fpart', listable=True)
def f_fpart(ctx: Ctx, x: Any) -> Any:
    return x - sp.sign(x) * sp.floor(sp.Abs(x))


@func('round', listable=True)
def f_round(ctx: Ctx, x: Any, digits: Any = sp.Integer(12)) -> Any:
    d = integer(digits)
    if is_mat(x):
        return sp.ImmutableMatrix(x.applyfunc(lambda e: f_round(ctx, e, digits)))
    if not need_expr(x).is_number:
        return sp.Function('round')(x, digits)
    return sp.Float(round(num(x), d), 15)


@func('mod', listable=True)
def f_mod(ctx: Ctx, a: Any, b: Any) -> Any:
    return a if b == 0 else sp.Mod(a, b)


@func('remain', listable=True)
def f_remain(ctx: Ctx, a: Any, b: Any) -> Any:
    return a if b == 0 else a - b * sp.sign(a / b) * sp.floor(sp.Abs(a / b))


@func('intdiv', listable=True)
def f_intdiv(ctx: Ctx, a: Any, b: Any) -> Any:
    return sp.sign(a / b) * sp.floor(sp.Abs(a / b))


@func('gcd', listable=True)
def f_gcd(ctx: Ctx, a: Any, b: Any) -> Any:
    return sp.gcd(need_expr(a), need_expr(b))


@func('lcm', listable=True)
def f_lcm(ctx: Ctx, a: Any, b: Any) -> Any:
    return sp.lcm(need_expr(a), need_expr(b))


@func('isprime', listable=True)
def f_isprime(ctx: Ctx, n: Any) -> Any:
    return sp.true if n.is_Integer and sp.isprime(int(n)) else sp.false


@func('ncr', listable=True)
def f_ncr(ctx: Ctx, n: Any, r: Any) -> Any:
    return sp.binomial(n, r) if not (n.is_number and r.is_number) else sp.expand_func(sp.binomial(n, r))


@func('npr', listable=True)
def f_npr(ctx: Ctx, n: Any, r: Any) -> Any:
    return sp.ff(n, r) if n.is_number and r.is_number else sp.factorial(n) / sp.factorial(n - r)


@func('approx')
def f_approx(ctx: Ctx, x: Any) -> Any:
    return approx_value(x)


@func('exact')
def f_exact(ctx: Ctx, x: Any, tol: Any = None) -> Any:
    t = num(tol) if tol is not None else 1e-12

    def one(e: Any) -> Any:
        if not isinstance(e, sp.Expr):
            return e
        return e.xreplace({f: sp.nsimplify(f, rational=True, tolerance=t) for f in e.atoms(sp.Float)})

    return map_value(one, x)


@func('getnum', listable=True)
def f_getnum(ctx: Ctx, x: Any) -> Any:
    return sp.fraction(sp.together(need_expr(x)))[0]


@func('getdenom', listable=True)
def f_getdenom(ctx: Ctx, x: Any) -> Any:
    return sp.fraction(sp.together(need_expr(x)))[1]


def _extreme(pick: Any, args: Any) -> Any:
    if len(args) == 1 and isinstance(args[0], TList):
        if not args[0]:
            raise TIError('Dimension: empty list')
        return pick(*args[0])
    if len(args) == 1 and is_mat(args[0]):
        return sp.ImmutableMatrix([[pick(*args[0].col(c)) for c in range(args[0].cols)]])
    if len(args) == 2:
        a, b = args
        if isinstance(a, TList) or isinstance(b, TList):
            la = a if isinstance(a, TList) else TList([a] * len(b))
            lb = b if isinstance(b, TList) else TList([b] * len(a))
            return TList(pick(x, y) for x, y in zip(la, lb))
        return pick(a, b)
    raise TIError('Argument: max/min take a list or two values')


@func('max')
def f_max(ctx: Ctx, *args: Any) -> Any:
    return _extreme(sp.Max, args)


@func('min')
def f_min(ctx: Ctx, *args: Any) -> Any:
    return _extreme(sp.Min, args)


def branch(ctx: Ctx, pairs: List[Any], otherwise: Any) -> Any:
    out = []
    for value_node, cond_node in pairs:
        cond = to_bool(ev(ctx, cond_node))
        if cond is sp.true:
            if not out:
                return ev(ctx, value_node)
            out.append((need_expr(ev(ctx, value_node)), True))
            return sp.Piecewise(*out)
        if cond is sp.false:
            continue
        out.append((need_expr(ev(ctx, value_node)), cond))
    if otherwise is not None:
        if not out:
            return ev(ctx, otherwise)
        out.append((need_expr(ev(ctx, otherwise)), True))
    elif not out:
        return sp.nan
    else:
        out.append((sp.nan, True))
    return sp.Piecewise(*out)


@func('when', raw=True)
def f_when(ctx: Ctx, cond: Node, yes: Node, no: Any = None, unknown: Any = None) -> Any:
    return branch(ctx, [(yes, cond)], no)


@func('piecewise', raw=True)
def f_piecewise(ctx: Ctx, *nodes: Node) -> Any:
    pairs = [(nodes[i], nodes[i + 1]) for i in range(0, len(nodes) - 1, 2)]
    return branch(ctx, pairs, nodes[-1] if len(nodes) % 2 == 1 else None)


@func('iffn', raw=True)
def f_iffn(ctx: Ctx, cond: Node, yes: Node, no: Any = None, unknown: Any = None) -> Any:
    return branch(ctx, [(yes, cond)], no)


@func('expr')
def f_expr(ctx: Ctx, s: Any) -> Any:
    if not isinstance(s, TStr):
        raise TIError('Data type: string expected')
    return ev(ctx, parse_expr(str(s)))


@func('string')
def f_string(ctx: Ctx, x: Any) -> Any:
    return TStr(to_text(x))


@func('char')
def f_char(ctx: Ctx, n: Any) -> Any:
    return TStr(chr(integer(n)))


@func('ord')
def f_ord(ctx: Ctx, s: Any) -> Any:
    return sp.Integer(ord(str(s)[0])) if isinstance(s, TStr) and s else sp.Integer(0)


@func('instring')
def f_instring(ctx: Ctx, s: Any, sub: Any, start: Any = sp.Integer(1)) -> Any:
    return sp.Integer(str(s).find(str(sub), integer(start) - 1) + 1)


@func('left')
def f_left(ctx: Ctx, v: Any, n: Any = None) -> Any:
    if isinstance(v, sp.core.relational.Relational):
        return v.lhs
    if isinstance(v, TStr):
        return TStr(v[:integer(n)] if n is not None else v)
    lst = as_list(v)
    return TList(lst[:integer(n)] if n is not None else lst)


@func('right')
def f_right(ctx: Ctx, v: Any, n: Any = None) -> Any:
    if isinstance(v, sp.core.relational.Relational):
        return v.rhs
    k = integer(n) if n is not None else None
    if isinstance(v, TStr):
        return TStr(v[len(v) - k:] if k is not None else v)
    lst = as_list(v)
    return TList(lst[len(lst) - k:] if k is not None else lst)


@func('mid')
def f_mid(ctx: Ctx, v: Any, start: Any, count: Any = None) -> Any:
    a = integer(start) - 1
    b = a + integer(count) if count is not None else None
    return TStr(v[a:b]) if isinstance(v, TStr) else TList(as_list(v)[a:b])


@func('seq', bind=(1,))
def f_seq(ctx: Ctx, e: Any, var: Any, lo: Any, hi: Any, step: Any = sp.Integer(1)) -> Any:
    if not isinstance(var, sp.Symbol):
        raise TIError('Argument: variable expected')
    a, b, s = num(lo), num(hi), num(step)
    if s == 0:
        raise TIError('Domain: step cannot be 0')
    out = TList()
    k = 0
    cur = lo
    while (s > 0 and num(cur) <= b + 1e-12) or (s < 0 and num(cur) >= b - 1e-12):
        out.append(map_value(lambda x: x.subs(var, cur) if isinstance(x, sp.Basic) else x, e))
        k += 1
        cur = lo + k * step
        if k > 20000:
            raise TIError('Resource: sequence too long')
    return out


@func('newlist')
def f_newlist(ctx: Ctx, n: Any) -> Any:
    return TList([sp.Integer(0)] * integer(n))


def _slice(lst: TList, start: Any, end: Any) -> List[Any]:
    a = integer(start) - 1 if start is not None else 0
    b = integer(end) if end is not None else len(lst)
    return list(lst[a:b])


@func('sum', bind=(1,))
def f_sum(ctx: Ctx, v: Any, *rest: Any) -> Any:
    if len(rest) == 3 and isinstance(rest[0], sp.Symbol):
        from .cmd_calculus import f_sigma

        return f_sigma(ctx, v, *rest)
    if is_mat(v):
        return sp.ImmutableMatrix([[sum(v.col(c), sp.Integer(0)) for c in range(v.cols)]])
    items = _slice(as_list(v), rest[0] if rest else None, rest[1] if len(rest) > 1 else None)
    return sp.Add(*items) if items else sp.Integer(0)


@func('product', bind=(1,))
def f_product(ctx: Ctx, v: Any, *rest: Any) -> Any:
    if len(rest) == 3 and isinstance(rest[0], sp.Symbol):
        from .cmd_calculus import f_pi

        return f_pi(ctx, v, *rest)
    items = _slice(as_list(v), rest[0] if rest else None, rest[1] if len(rest) > 1 else None)
    return sp.Mul(*items) if items else sp.Integer(1)


def expand_freq(v: Any, freq: Any) -> List[Any]:
    lst = list(as_list(v))
    if freq is None:
        return lst
    fl = as_list(freq)
    if len(fl) != len(lst):
        raise TIError('Dimension mismatch')
    out: List[Any] = []
    for x, f in zip(lst, fl):
        out.extend([x] * integer(f, 'frequency'))
    return out


@func('mean')
def f_mean(ctx: Ctx, v: Any, freq: Any = None) -> Any:
    items = expand_freq(v, freq)
    if not items:
        raise TIError('Dimension: empty list')
    return sp.Add(*items) / len(items)


@func('median')
def f_median(ctx: Ctx, v: Any, freq: Any = None) -> Any:
    items = sorted(expand_freq(v, freq), key=num)
    if not items:
        raise TIError('Dimension: empty list')
    n = len(items)
    return items[n // 2] if n % 2 else (items[n // 2 - 1] + items[n // 2]) / 2


def _var(v: Any, freq: Any, sample: bool) -> Any:
    items = expand_freq(v, freq)
    n = len(items)
    if n < (2 if sample else 1):
        raise TIError('Dimension: not enough data')
    m = sp.Add(*items) / n
    return sp.Add(*[(x - m) ** 2 for x in items]) / (n - 1 if sample else n)


func('varsamp', 'variance')(lambda ctx, v, freq=None: _var(v, freq, True))
func('varpop')(lambda ctx, v, freq=None: _var(v, freq, False))
func('stdevsamp')(lambda ctx, v, freq=None: sp.sqrt(_var(v, freq, True)))
func('stdevpop')(lambda ctx, v, freq=None: sp.sqrt(_var(v, freq, False)))


@func('cumulativesum')
def f_cumsum(ctx: Ctx, v: Any) -> Any:
    out, total = TList(), sp.Integer(0)
    for x in as_list(v):
        total = total + x
        out.append(total)
    return out


@func('deltalist')
def f_delta(ctx: Ctx, v: Any) -> Any:
    lst = as_list(v)
    return TList(lst[i + 1] - lst[i] for i in range(len(lst) - 1))


@func('count')
def f_count(ctx: Ctx, *args: Any) -> Any:
    total = 0
    for a in args:
        total += sum(1 for x in a if isinstance(x, sp.Expr) and x.is_number) if isinstance(a, TList) else 1
    return sp.Integer(total)


@func('countif')
def f_countif(ctx: Ctx, v: Any, crit: Any) -> Any:
    return sp.Integer(sum(1 for x in as_list(v) if x == crit or to_text(x) == to_text(crit)))


@func('sumif')
def f_sumif(ctx: Ctx, v: Any, crit: Any, sums: Any = None) -> Any:
    lst = as_list(v)
    src = as_list(sums) if sums is not None else lst
    return sp.Add(*[s for x, s in zip(lst, src) if x == crit])


@func('rand')
def f_rand(ctx: Ctx, n: Any = None) -> Any:
    if n is None:
        return sp.Float(RNG.random(), 15)
    return TList(sp.Float(RNG.random(), 15) for _ in range(integer(n)))


@func('randint')
def f_randint(ctx: Ctx, lo: Any, hi: Any, n: Any = None) -> Any:
    a, b = integer(lo), integer(hi)
    if n is None:
        return sp.Integer(RNG.randint(min(a, b), max(a, b)))
    return TList(sp.Integer(RNG.randint(min(a, b), max(a, b))) for _ in range(integer(n)))


@func('randnorm')
def f_randnorm(ctx: Ctx, mu: Any, sigma: Any, n: Any = None) -> Any:
    if n is None:
        return sp.Float(RNG.gauss(num(mu), num(sigma)), 15)
    return TList(sp.Float(RNG.gauss(num(mu), num(sigma)), 15) for _ in range(integer(n)))


@func('randbin')
def f_randbin(ctx: Ctx, n: Any, p: Any, trials: Any = None) -> Any:
    def one() -> Any:
        return sp.Integer(sum(1 for _ in range(integer(n)) if RNG.random() < num(p)))

    return one() if trials is None else TList(one() for _ in range(integer(trials)))


@func('randsamp')
def f_randsamp(ctx: Ctx, v: Any, n: Any, norepl: Any = sp.Integer(0)) -> Any:
    lst = list(as_list(v))
    k = integer(n)
    if integer(norepl) != 0:
        if k > len(lst):
            raise TIError('Domain: sample larger than list')
        return TList(RNG.sample(lst, k))
    return TList(RNG.choice(lst) for _ in range(k))


@command('randseed')
def c_randseed(ctx: Ctx, n: Node) -> Any:
    RNG.seed(integer(ev(ctx, n)))
    return None


def _names(nodes: Any) -> List[str]:
    out = []
    for n in nodes:
        if n[0] != 'name':
            raise TIError('Argument: variable name expected')
        out.append(n[1].lower())
    return out


@command('delvar')
def c_delvar(ctx: Ctx, *nodes: Node) -> Any:
    for key in _names(nodes):
        if key.endswith('.'):
            for k in [k for k in ctx.vars if k.startswith(key)]:
                del ctx.vars[k]
        ctx.vars.pop(key, None)
    ctx.changed = True
    return None


@command('clearaz')
def c_clearaz(ctx: Ctx) -> Any:
    for k in [k for k in ctx.vars if len(k) == 1 and k.isalpha()]:
        del ctx.vars[k]
    ctx.changed = True
    return None


@command('clrhist')
def c_clrhist(ctx: Ctx) -> Any:
    ctx.clear_history = True
    return None


@command('disp')
def c_disp(ctx: Ctx, *nodes: Node) -> Any:
    from .core import finalize

    parts = []
    for n in nodes:
        v = finalize(ctx, ev(ctx, n), n)
        parts.append(str(v) if isinstance(v, TStr) else to_text(v))
    ctx.disp.append(' '.join(parts))
    return None


def _sort(ctx: Ctx, nodes: Any, reverse: bool) -> Any:
    keys = _names(nodes)
    lists = [ctx.lookup(k) for k in keys]
    if not lists or any(not isinstance(l, TList) for l in lists) or len({len(l) for l in lists}) != 1:
        raise TIError('Data type: list variable(s) of equal length expected')
    order = sorted(range(len(lists[0])), key=lambda i: num(lists[0][i]), reverse=reverse)
    for k, l in zip(keys, lists):
        ctx.assign(k, TList(l[i] for i in order))
    ctx.changed = True
    return None


command('sorta')(lambda ctx, *nodes: _sort(ctx, nodes, False))
command('sortd')(lambda ctx, *nodes: _sort(ctx, nodes, True))


@command('return')
def c_return(ctx: Ctx, node: Any = None) -> Any:
    from .core import finalize

    raise Control('return', finalize(ctx, ev(ctx, node), node) if node is not None else None)


command('stop')(lambda ctx: (_ for _ in ()).throw(Control('stop')))
command('exit')(lambda ctx: (_ for _ in ()).throw(Control('exit')))
command('cycle')(lambda ctx: (_ for _ in ()).throw(Control('cycle')))
command('lock', 'unlock')(lambda ctx, *nodes: None)

sources.cmd_matrix.py:
"""Matrix and vector commands."""
from typing import Any, List

import sympy as sp

from .cmd_math import RNG, as_list, integer
from .core import Ctx, command, ev, func, finalize, is_mat, need_expr, sym
from .parser import Node, TIError
from .values import TList, TStr


def mat(v: Any) -> Any:
    if not is_mat(v):
        raise TIError('Data type: matrix expected')
    return v


def square(v: Any) -> Any:
    m = mat(v)
    if m.rows != m.cols:
        raise TIError('Dimension: square matrix expected')
    return m


def im(m: Any) -> Any:
    return sp.ImmutableMatrix(m)


def vec(v: Any) -> List[Any]:
    if isinstance(v, TList):
        return list(v)
    if is_mat(v) and (v.rows == 1 or v.cols == 1):
        return list(v)
    raise TIError('Data type: vector expected')


def like(v: Any, items: List[Any]) -> Any:
    if isinstance(v, TList):
        return TList(items)
    return im([items]) if v.rows == 1 else im([[i] for i in items])


def row_index(m: Any, i: Any) -> int:
    k = integer(i)
    if not 1 <= k <= m.rows:
        raise TIError('Domain: invalid row')
    return k - 1


@func('det')
def f_det(ctx: Ctx, m: Any) -> Any:
    return sp.simplify(square(m).det())


@func('rref')
def f_rref(ctx: Ctx, m: Any) -> Any:
    return im(mat(m).rref(simplify=True)[0])


@func('ref')
def f_ref(ctx: Ctx, m: Any) -> Any:
    out = mat(m).echelon_form(simplify=True).as_mutable()
    for r in range(out.rows):
        lead = next((out[r, c] for c in range(out.cols) if out[r, c] != 0), None)
        if lead is not None:
            out[r, :] = (out[r, :] / lead).applyfunc(sp.simplify)
    return im(out)


@func('transpose')
def f_transpose(ctx: Ctx, m: Any) -> Any:
    return im(mat(m).T)


@func('trace')
def f_trace(ctx: Ctx, m: Any) -> Any:
    return square(m).trace()


@func('eigvl')
def f_eigvl(ctx: Ctx, m: Any) -> Any:
    vals: List[Any] = []
    for v, k in square(m).eigenvals().items():
        vals.extend([v] * k)
    try:
        vals.sort(key=lambda v: (-float(sp.re(sp.N(v))), float(sp.im(sp.N(v)))))
    except (TypeError, ValueError):
        pass
    return TList(sp.simplify(v) for v in vals)


@func('eigvc')
def f_eigvc(ctx: Ctx, m: Any) -> Any:
    cols: List[Any] = []
    triples = square(m).eigenvects()
    try:
        triples.sort(key=lambda t: -float(sp.re(sp.N(t[0]))))
    except (TypeError, ValueError):
        pass
    for _, _, vecs in triples:
        for v in vecs:
            n = sp.sqrt(sum(sp.Abs(x) ** 2 for x in v))
            cols.append((v / n).applyfunc(sp.simplify))
    if not cols:
        raise TIError('Unable to compute eigenvectors')
    return im(sp.Matrix.hstack(*cols))


@func('charpoly', bind=(1,))
def f_charpoly(ctx: Ctx, m: Any, var: Any) -> Any:
    return sp.expand((var * sp.eye(square(m).rows) - m).det())


@func('norm')
def f_norm(ctx: Ctx, v: Any) -> Any:
    return sp.sqrt(sum(sp.Abs(x) ** 2 for x in (v if isinstance(v, TList) else mat(v))))


func('rownorm')(lambda ctx, m: sp.Max(*[sum(sp.Abs(x) for x in mat(m).row(r)) for r in range(m.rows)]))
func('colnorm')(lambda ctx, m: sp.Max(*[sum(sp.Abs(x) for x in mat(m).col(c)) for c in range(m.cols)]))


@func('unitv')
def f_unitv(ctx: Ctx, v: Any) -> Any:
    items = vec(v)
    n = sp.sqrt(sum(sp.Abs(x) ** 2 for x in items))
    if n == 0:
        raise TIError('Domain: zero vector')
    return like(v, [sp.simplify(x / n) for x in items])


@func('crossp')
def f_crossp(ctx: Ctx, a: Any, b: Any) -> Any:
    u, w = vec(a), vec(b)
    if len(u) == 2:
        u = u + [sp.Integer(0)]
    if len(w) == 2:
        w = w + [sp.Integer(0)]
    if len(u) != 3 or len(w) != 3:
        raise TIError('Dimension: 2 or 3 element vectors expected')
    return like(a, [u[1] * w[2] - u[2] * w[1], u[2] * w[0] - u[0] * w[2], u[0] * w[1] - u[1] * w[0]])


@func('dotp')
def f_dotp(ctx: Ctx, a: Any, b: Any) -> Any:
    u, w = vec(a), vec(b)
    if len(u) != len(w):
        raise TIError('Dimension mismatch')
    return sp.expand(sum(x * y for x, y in zip(u, w)))


@func('dim')
def f_dim(ctx: Ctx, v: Any) -> Any:
    if is_mat(v):
        return TList([sp.Integer(v.rows), sp.Integer(v.cols)])
    if isinstance(v, (TList, TStr)):
        return sp.Integer(len(v))
    raise TIError('Data type: list, matrix or string expected')


func('rowdim')(lambda ctx, m: sp.Integer(mat(m).rows))
func('coldim')(lambda ctx, m: sp.Integer(mat(m).cols))


@func('augment')
def f_augment(ctx: Ctx, a: Any, b: Any) -> Any:
    if isinstance(a, TList) and isinstance(b, TList):
        return TList(list(a) + list(b))
    if mat(a).rows != mat(b).rows:
        raise TIError('Dimension mismatch')
    return im(sp.Matrix.hstack(a, b))


@func('colaugment')
def f_colaugment(ctx: Ctx, a: Any, b: Any) -> Any:
    if mat(a).cols != mat(b).cols:
        raise TIError('Dimension mismatch')
    return im(sp.Matrix.vstack(a, b))


@func('submat')
def f_submat(ctx: Ctx, m: Any, r1: Any = sp.Integer(1), c1: Any = sp.Integer(1), r2: Any = None, c2: Any = None) -> Any:
    m = mat(m)
    a, b = integer(r1), integer(c1)
    c, d = (integer(r2) if r2 is not None else m.rows), (integer(c2) if c2 is not None else m.cols)
    if not (1 <= a <= c <= m.rows and 1 <= b <= d <= m.cols):
        raise TIError('Domain: invalid sub-matrix')
    return im(m[a - 1:c, b - 1:d])


@func('diag')
def f_diag(ctx: Ctx, v: Any) -> Any:
    if is_mat(v) and v.rows == v.cols and v.rows > 1:
        return im([[v[i, i] for i in range(v.rows)]])
    return im(sp.diag(*vec(v)))


func('identity')(lambda ctx, n: im(sp.eye(integer(n))))
func('newmat')(lambda ctx, r, c: im(sp.zeros(integer(r), integer(c))))
func('randmat')(lambda ctx, r, c: im(sp.Matrix(integer(r), integer(c), lambda i, j: sp.Integer(RNG.randint(-9, 9)))))


@func('constructmat', bind=(1, 2))
def f_constructmat(ctx: Ctx, e: Any, v1: Any, v2: Any, rows: Any, cols: Any) -> Any:
    return im(sp.Matrix(integer(rows), integer(cols), lambda i, j: need_expr(e).subs({v1: i + 1, v2: j + 1})))


@func('mrow')
def f_mrow(ctx: Ctx, k: Any, m: Any, i: Any) -> Any:
    out = mat(m).as_mutable()
    r = row_index(out, i)
    out[r, :] = out[r, :] * k
    return im(out)


@func('mrowadd')
def f_mrowadd(ctx: Ctx, k: Any, m: Any, i1: Any, i2: Any) -> Any:
    out = mat(m).as_mutable()
    a, b = row_index(out, i1), row_index(out, i2)
    out[b, :] = out[b, :] + out[a, :] * k
    return im(out)


@func('rowadd')
def f_rowadd(ctx: Ctx, m: Any, i1: Any, i2: Any) -> Any:
    return f_mrowadd(ctx, sp.Integer(1), m, i1, i2)


@func('rowswap')
def f_rowswap(ctx: Ctx, m: Any, i1: Any, i2: Any) -> Any:
    out = mat(m).as_mutable()
    out.row_swap(row_index(out, i1), row_index(out, i2))
    return im(out)


@func('simult')
def f_simult(ctx: Ctx, coef: Any, const: Any) -> Any:
    a = square(coef)
    if a.det() == 0:
        raise TIError('Singular matrix')
    return im((a.inv() * mat(const)).applyfunc(sp.simplify))


@func('mat►list', 'mat2list')
def f_mat2list(ctx: Ctx, m: Any) -> Any:
    return TList(list(mat(m)))


@func('list►mat', 'list2mat')
def f_list2mat(ctx: Ctx, v: Any, per_row: Any = None) -> Any:
    items = list(as_list(v))
    n = integer(per_row) if per_row is not None else len(items)
    while len(items) % n:
        items.append(sp.Integer(0))
    return im([items[i:i + n] for i in range(0, len(items), n)])


def _store(ctx: Ctx, node: Node, value: Any) -> None:
    if node[0] != 'name':
        raise TIError('Argument: variable name expected')
    ctx.assign(node[1].lower(), finalize(ctx, value))
    ctx.changed = True


@command('lu')
def c_lu(ctx: Ctx, m: Node, l: Node, u: Node, p: Node) -> Any:
    a = square(ev(ctx, m))
    try:
        lower, upper, perm = a.LUdecomposition()
    except Exception:
        raise TIError('Singular matrix')
    pm = sp.eye(a.rows).permuteFwd(perm)
    _store(ctx, l, im(lower.applyfunc(sp.simplify)))
    _store(ctx, u, im(upper.applyfunc(sp.simplify)))
    _store(ctx, p, im(pm))
    return None


@command('qr')
def c_qr(ctx: Ctx, m: Node, q: Node, r: Node) -> Any:
    try:
        qm, rm = mat(ev(ctx, m)).QRdecomposition()
    except Exception:
        raise TIError('Unable to factor matrix')
    _store(ctx, q, im(qm.applyfunc(sp.simplify)))
    _store(ctx, r, im(rm.applyfunc(sp.simplify)))
    return None

sources.cmd_prob.py:
"""Probability distributions."""
from typing import Any, Callable

import mpmath as mp
import sympy as sp

from .cmd_math import integer, num
from .core import Ctx, func
from .parser import TIError
from .values import TList


def bound(v: Any) -> Any:
    if v is sp.oo:
        return mp.inf
    if v is -sp.oo:
        return -mp.inf
    return mp.mpf(num(v))


def out(v: Any) -> Any:
    return sp.Float(float(v), 15)


def prob(v: Any) -> float:
    p = num(v)
    if not 0 <= p <= 1:
        raise TIError('Domain: probability must be between 0 and 1')
    return p


def invert(cdf: Callable[[Any], Any], area: float, lo: float, hi: float) -> Any:
    if not 0 < area < 1:
        raise TIError('Domain: area must be between 0 and 1')
    a, b = mp.mpf(lo), mp.mpf(hi)
    while cdf(a) > area:
        a = a * 2 if a < 0 else a - 1
    while cdf(b) < area:
        b = b * 2 if b > 0 else b + 1
    for _ in range(200):
        m = (a + b) / 2
        if cdf(m) < area:
            a = m
        else:
            b = m
        if b - a < mp.mpf(10) ** -14 * max(1, abs(m)):
            break
    return (a + b) / 2


def t_cdf(x: Any, df: Any) -> Any:
    if x == mp.inf:
        return mp.mpf(1)
    if x == -mp.inf:
        return mp.mpf(0)
    ib = mp.betainc(df / 2, mp.mpf(1) / 2, 0, df / (df + x * x), regularized=True)
    return 1 - ib / 2 if x > 0 else ib / 2


def chi_cdf(x: Any, df: Any) -> Any:
    if x <= 0:
        return mp.mpf(0)
    return mp.mpf(1) if x == mp.inf else mp.gammainc(df / 2, 0, x / 2, regularized=True)


def f_cdf_(x: Any, d1: Any, d2: Any) -> Any:
    if x <= 0:
        return mp.mpf(0)
    return mp.mpf(1) if x == mp.inf else mp.betainc(d1 / 2, d2 / 2, 0, d1 * x / (d1 * x + d2), regularized=True)


@func('normpdf', listable=True)
def f_normpdf(ctx: Ctx, x: Any, mu: Any = sp.Integer(0), sigma: Any = sp.Integer(1)) -> Any:
    return out(mp.npdf(num(x), num(mu), num(sigma)))


@func('normcdf')
def f_normcdf(ctx: Ctx, lo: Any, hi: Any, mu: Any = sp.Integer(0), sigma: Any = sp.Integer(1)) -> Any:
    m, s = num(mu), num(sigma)
    if s <= 0:
        raise TIError('Domain: σ must be positive')
    return out(mp.ncdf(bound(hi), m, s) - mp.ncdf(bound(lo), m, s))


@func('invnorm', listable=True)
def f_invnorm(ctx: Ctx, area: Any, mu: Any = sp.Integer(0), sigma: Any = sp.Integer(1)) -> Any:
    a = num(area)
    if not 0 < a < 1:
        raise TIError('Domain: area must be between 0 and 1')
    return out(num(mu) + num(sigma) * mp.sqrt(2) * mp.erfinv(2 * mp.mpf(a) - 1))


@func('tpdf', listable=True)
def f_tpdf(ctx: Ctx, x: Any, df: Any) -> Any:
    v, t = mp.mpf(num(df)), mp.mpf(num(x))
    return out(mp.gamma((v + 1) / 2) / (mp.sqrt(v * mp.pi) * mp.gamma(v / 2)) * (1 + t * t / v) ** (-(v + 1) / 2))


@func('tcdf')
def f_tcdf(ctx: Ctx, lo: Any, hi: Any, df: Any) -> Any:
    v = mp.mpf(num(df))
    return out(t_cdf(bound(hi), v) - t_cdf(bound(lo), v))


@func('invt', listable=True)
def f_invt(ctx: Ctx, area: Any, df: Any) -> Any:
    v = mp.mpf(num(df))
    return out(invert(lambda x: t_cdf(x, v), num(area), -10, 10))


@func('χ²pdf', 'chi2pdf', listable=True)
def f_chipdf(ctx: Ctx, x: Any, df: Any) -> Any:
    k, t = mp.mpf(num(df)), mp.mpf(num(x))
    return out(0 if t < 0 else t ** (k / 2 - 1) * mp.exp(-t / 2) / (2 ** (k / 2) * mp.gamma(k / 2)))


@func('χ²cdf', 'chi2cdf')
def f_chicdf(ctx: Ctx, lo: Any, hi: Any, df: Any) -> Any:
    k = mp.mpf(num(df))
    return out(chi_cdf(bound(hi), k) - chi_cdf(bound(lo), k))


@func('invχ²', 'invchi2', listable=True)
def f_invchi(ctx: Ctx, area: Any, df: Any) -> Any:
    k = mp.mpf(num(df))
    return out(invert(lambda x: chi_cdf(x, k), num(area), 0, 10))


@func('fpdf', listable=True)
def f_fpdf(ctx: Ctx, x: Any, d1: Any, d2: Any) -> Any:
    a, b, t = mp.mpf(num(d1)), mp.mpf(num(d2)), mp.mpf(num(x))
    if t < 0:
        return out(0)
    return out(mp.sqrt((a * t) ** a * b ** b / (a * t + b) ** (a + b)) / (t * mp.beta(a / 2, b / 2)) if t > 0 else 0)


@func('fcdf')
def f_fcdf(ctx: Ctx, lo: Any, hi: Any, d1: Any, d2: Any) -> Any:
    a, b = mp.mpf(num(d1)), mp.mpf(num(d2))
    return out(f_cdf_(bound(hi), a, b) - f_cdf_(bound(lo), a, b))


@func('invf', listable=True)
def f_invf(ctx: Ctx, area: Any, d1: Any, d2: Any) -> Any:
    a, b = mp.mpf(num(d1)), mp.mpf(num(d2))
    return out(invert(lambda x: f_cdf_(x, a, b), num(area), 0, 10))


def binom_p(n: int, p: float, k: int) -> Any:
    return mp.binomial(n, k) * mp.mpf(p) ** k * (1 - mp.mpf(p)) ** (n - k) if 0 <= k <= n else mp.mpf(0)


@func('binompdf')
def f_binompdf(ctx: Ctx, n: Any, p: Any, x: Any = None) -> Any:
    nn, pp = integer(n), prob(p)
    if x is None:
        return TList(out(binom_p(nn, pp, k)) for k in range(nn + 1))
    if isinstance(x, TList):
        return TList(out(binom_p(nn, pp, integer(k))) for k in x)
    return out(binom_p(nn, pp, integer(x)))


def krange(lo: Any, hi: Any, top: int) -> range:
    a = 0 if lo is -sp.oo else max(0, integer(lo))
    b = top if hi is sp.oo else min(top, integer(hi))
    return range(a, b + 1)


@func('binomcdf')
def f_binomcdf(ctx: Ctx, n: Any, p: Any, lo: Any = None, hi: Any = None) -> Any:
    nn, pp = integer(n), prob(p)
    if lo is None:
        total, acc = mp.mpf(0), TList()
        for k in range(nn + 1):
            total += binom_p(nn, pp, k)
            acc.append(out(total))
        return acc
    if hi is None:
        lo, hi = sp.Integer(0), lo
    return out(mp.fsum(binom_p(nn, pp, k) for k in krange(lo, hi, nn)))


@func('geompdf')
def f_geompdf(ctx: Ctx, p: Any, x: Any) -> Any:
    pp, k = prob(p), integer(x)
    return out(pp * (1 - pp) ** (k - 1) if k >= 1 else 0)


@func('geomcdf')
def f_geomcdf(ctx: Ctx, p: Any, lo: Any, hi: Any = None) -> Any:
    pp = prob(p)
    if hi is None:
        lo, hi = sp.Integer(1), lo
    a = 1 if lo is -sp.oo else max(1, integer(lo))
    upper = mp.mpf(1) if hi is sp.oo else 1 - (1 - mp.mpf(pp)) ** integer(hi)
    return out(max(0, upper - (1 - (1 - mp.mpf(pp)) ** (a - 1))))


def pois_p(lam: float, k: int) -> Any:
    return mp.exp(-lam) * mp.mpf(lam) ** k / mp.factorial(k) if k >= 0 else mp.mpf(0)


@func('poisspdf')
def f_poisspdf(ctx: Ctx, lam: Any, x: Any) -> Any:
    return out(pois_p(num(lam), integer(x)))


@func('poisscdf')
def f_poisscdf(ctx: Ctx, lam: Any, lo: Any, hi: Any = None) -> Any:
    l = num(lam)
    if hi is None:
        lo, hi = sp.Integer(0), lo
    a = 0 if lo is -sp.oo else max(0, integer(lo))
    if hi is sp.oo:
        return out(1 - mp.fsum(pois_p(l, k) for k in range(a)))
    return out(mp.fsum(pois_p(l, k) for k in range(a, integer(hi) + 1)))

sources.core.py:
"""Evaluator: AST -> SymPy values, namespaces, modes and arithmetic."""
from typing import Any, Callable, Dict, List, Optional, Set, Tuple

import sympy as sp

from .parser import Node, TIError, names_in, parse_statement
from .values import Control, TList, TStr, UFunc

MAX_DEPTH = 60
_SYMS: Dict[str, sp.Symbol] = {}


def sym(name: str) -> sp.Symbol:
    key = name.lower()
    if key not in _SYMS:
        _SYMS[key] = sp.Symbol(key, real=True)
    return _SYMS[key]


class Engine:
    def __init__(self) -> None:
        self.spaces: Dict[str, Dict[str, Any]] = {}
        self.angle = 'RAD'
        self.calc = 'AUTO'
        self.digits = 6

    def space(self, ns: str) -> Dict[str, Any]:
        return self.spaces.setdefault(ns, {})


ENGINE = Engine()
FUNCS: Dict[str, Tuple[Callable[..., Any], Dict[str, Any]]] = {}
CMDS: Dict[str, Callable[..., Any]] = {}


def func(*names: str, bind: Tuple[int, ...] = (), raw: bool = False, listable: bool = False, bind_rest: bool = False) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def deco(fn: Callable[..., Any]) -> Callable[..., Any]:
        for n in names:
            FUNCS[n.lower()] = (fn, {'bind': bind, 'raw': raw, 'listable': listable, 'bind_rest': bind_rest})
        return fn

    return deco


def command(*names: str) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def deco(fn: Callable[..., Any]) -> Callable[..., Any]:
        for n in names:
            CMDS[n.lower()] = fn
        return fn

    return deco


class Ctx:
    def __init__(self, ns: str, approx: bool = False, inputs: Optional[List[str]] = None):
        self.engine = ENGINE
        self.ns = ns
        self.vars = ENGINE.space(ns)
        self.approx = approx or ENGINE.calc == 'APPROX'
        self.frames: List[Dict[str, Any]] = []
        self.shield: List[Set[str]] = []
        self.domain: Dict[sp.Symbol, Any] = {}
        self.de: Optional[Tuple[str, sp.Symbol, Any]] = None
        self.disp: List[str] = []
        self.inputs = inputs or []
        self.input_pos = 0
        self.changed = False
        self.depth = 0
        self.steps = 0
        self.src = ''
        self.clear_history = False

    @property
    def deg(self) -> bool:
        return self.engine.angle == 'DEG'

    def lookup(self, key: str) -> Any:
        for s in reversed(self.shield):
            if key in s:
                return None
        for frame in reversed(self.frames):
            if key in frame:
                return frame[key]
        return self.vars.get(key)

    def assign(self, key: str, value: Any) -> None:
        if self.frames and self.frames[-1].get('#func'):
            self.frames[-1][key] = value
            return
        for frame in reversed(self.frames):
            if key in frame:
                frame[key] = value
                return
        self.vars[key] = value
        self.changed = True

    def tick(self) -> None:
        self.steps += 1
        if self.steps > 400000:
            raise TIError('Break: program stopped (too many steps)')


def is_mat(v: Any) -> bool:
    return isinstance(v, sp.MatrixBase)


def is_bool(v: Any) -> bool:
    return isinstance(v, (bool, sp.logic.boolalg.Boolean)) and not isinstance(v, sp.Symbol)


def as_expr(v: Any) -> Any:
    if isinstance(v, bool):
        return sp.true if v else sp.false
    if isinstance(v, (int, float)):
        return sp.sympify(v)
    return v


def need_expr(v: Any, what: str = 'argument') -> Any:
    if isinstance(v, (TList, TStr, UFunc)) or is_mat(v) or v is None:
        raise TIError(f'Data type: invalid {what}')
    return v


def map_value(fn: Callable[[Any], Any], v: Any) -> Any:
    if isinstance(v, TList):
        return TList(map_value(fn, x) for x in v)
    if is_mat(v):
        return sp.ImmutableMatrix(v.applyfunc(fn))
    if isinstance(v, (TStr, UFunc)) or v is None:
        return v
    return fn(v)


def approx_value(v: Any) -> Any:
    def one(e: Any) -> Any:
        if isinstance(e, sp.Basic):
            try:
                out = e.evalf(15)
                if isinstance(out, sp.Expr) and out.is_number and not out.is_Float and out.is_real is False:
                    out = sp.N(out, 15)
                return out
            except Exception:
                return e
        return e

    return map_value(one, v)


def has_float(v: Any) -> bool:
    if isinstance(v, TList):
        return any(has_float(x) for x in v)
    if is_mat(v):
        return any(has_float(x) for x in v)
    return isinstance(v, sp.Basic) and bool(v.atoms(sp.Float))


def tidy(e: Any) -> Any:
    if not isinstance(e, sp.Expr) or e.is_Atom:
        return e
    try:
        if e.is_number:
            if e.has(sp.Float):
                return e
            r = sp.radsimp(sp.expand(e))
            return r if sp.count_ops(r) <= sp.count_ops(e) else e
        r = e
        if any(d.free_symbols for d in sp.denom(sp.together(e)).as_ordered_factors()):
            c = sp.factor(sp.together(e))
            if sp.count_ops(c) < sp.count_ops(r):
                r = c
        if r.has(sp.sin, sp.cos, sp.tan) and sp.count_ops(r) < 60:
            t = sp.trigsimp(r)
            trig = sp.functions.elementary.trigonometric.TrigonometricFunction
            if sp.count_ops(t) < sp.count_ops(r) and len(t.atoms(trig)) < len(r.atoms(trig)):
                r = t
        return r
    except Exception:
        return e


def finalize(ctx: Ctx, value: Any, node: Optional[Node] = None) -> Any:
    if node is not None and node[0] in ('bin', 'neg', 'post'):
        value = map_value(tidy, value)
    if ctx.approx or has_float(value):
        value = approx_value(value)
    return value


def rel_map(fn: Callable[[Any], Any], r: Any) -> Any:
    return r.func(fn(r.lhs), fn(r.rhs))


def arith(op: str, a: Any, b: Any) -> Any:
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        if b == 0:
            return sp.nan
        return a / b
    if b == 0 and a == 0:
        return sp.nan
    return sp.Pow(a, b)


def binop(op: str, a: Any, b: Any) -> Any:
    if op == '&':
        if isinstance(a, TStr) and isinstance(b, TStr):
            return TStr(str(a) + str(b))
        raise TIError('Data type: & needs two strings')
    if isinstance(a, TStr) or isinstance(b, TStr) or isinstance(a, UFunc) or isinstance(b, UFunc):
        raise TIError('Data type: invalid operand')
    o = op[-1]
    dot = len(op) == 2
    if isinstance(a, TList) or isinstance(b, TList):
        if isinstance(a, TList) and isinstance(b, TList):
            if len(a) != len(b):
                raise TIError('Dimension mismatch')
            return TList(binop(op, x, y) for x, y in zip(a, b))
        if isinstance(a, TList):
            return TList(binop(op, x, b) for x in a)
        return TList(binop(op, a, y) for y in b)
    a, b = as_expr(a), as_expr(b)
    if is_mat(a) or is_mat(b):
        return mat_op(o, dot, a, b)
    if isinstance(a, sp.core.relational.Relational) or isinstance(b, sp.core.relational.Relational):
        if isinstance(a, sp.core.relational.Relational) and isinstance(b, sp.core.relational.Relational):
            return a.func(arith(o, a.lhs, b.lhs), arith(o, a.rhs, b.rhs))
        if isinstance(a, sp.core.relational.Relational):
            return rel_map(lambda s: arith(o, s, b), a)
        return rel_map(lambda s: arith(o, a, s), b)
    if is_bool(a) or is_bool(b):
        raise TIError('Data type: invalid operand')
    return arith(o, a, b)


def mat_op(o: str, dot: bool, a: Any, b: Any) -> Any:
    try:
        if is_mat(a) and is_mat(b):
            if dot or o in '+-':
                if a.shape != b.shape:
                    raise TIError('Dimension mismatch')
                return sp.ImmutableMatrix(a.rows, a.cols, [arith(o, x, y) for x, y in zip(a, b)])
            if o == '*':
                if a.cols != b.rows:
                    raise TIError('Dimension mismatch')
                return sp.ImmutableMatrix(a * b)
            raise TIError('Data type: invalid matrix operation')
        if is_mat(a):
            if dot or o in '*/':
                return sp.ImmutableMatrix(a.applyfunc(lambda x: arith(o, x, b)))
            if o in '+-':
                if a.rows != a.cols:
                    return sp.ImmutableMatrix(a.applyfunc(lambda x: arith(o, x, b)))
                return sp.ImmutableMatrix(a + b * sp.eye(a.rows) if o == '+' else a - b * sp.eye(a.rows))
            if a.rows != a.cols or not b.is_Integer:
                raise TIError('Dimension: square matrix and integer power required')
            if b < 0 and a.det() == 0:
                raise TIError('Singular matrix')
            return sp.ImmutableMatrix(a ** int(b))
        if dot or o == '*':
            return sp.ImmutableMatrix(b.applyfunc(lambda y: arith(o, a, y)))
        if o in '+-':
            return mat_op(o, dot, a * sp.eye(b.rows) if b.rows == b.cols else b.applyfunc(lambda y: a), b)
        raise TIError('Data type: invalid matrix operation')
    except sp.matrices.exceptions.NonInvertibleMatrixError:
        raise TIError('Singular matrix')


def number(ctx: Ctx, text: str) -> Any:
    if '.' in text or 'e' in text:
        if ctx.engine.calc == 'EXACT' and not ctx.approx:
            return sp.Rational(text)
        return sp.Float(text, 15)
    return sp.Integer(text)


CONSTS = {'π': sp.pi, 'ℯ': sp.E, '𝒊': sp.I, '∞': sp.oo}
REL = {'=': sp.Eq, '≠': sp.Ne, '<': sp.Lt, '>': sp.Gt, '≤': sp.Le, '≥': sp.Ge}


def ev(ctx: Ctx, node: Node) -> Any:
    kind = node[0]
    if kind == 'num':
        return number(ctx, node[1])
    if kind == 'const':
        return CONSTS[node[1]]
    if kind == 'str':
        return TStr(node[1])
    if kind == 'name':
        return ev_name(ctx, node[1])
    if kind == 'call':
        return call(ctx, node[1], node[2])
    if kind == 'bin':
        return binop(node[1], ev(ctx, node[2]), ev(ctx, node[3]))
    if kind == 'neg':
        v = ev(ctx, node[1])
        return binop('*', sp.Integer(-1), v)
    if kind == 'post':
        return postfix(ctx, node[1], ev(ctx, node[2]))
    if kind == 'list':
        return TList(ev(ctx, n) for n in node[1])
    if kind == 'mat':
        rows = [[need_expr(as_expr(ev(ctx, c)), 'matrix element') for c in row] for row in node[1]]
        if len({len(r) for r in rows}) != 1:
            raise TIError('Dimension: rows must be the same length')
        return sp.ImmutableMatrix(rows)
    if kind == 'idx':
        return index(ev(ctx, node[1]), [ev(ctx, i) for i in node[2]])
    if kind == 'with':
        return ev_with(ctx, node[1], node[2])
    if kind == 'logic':
        a, b = to_bool(ev(ctx, node[2])), to_bool(ev(ctx, node[3]))
        return {'and': sp.And, 'or': sp.Or, 'xor': sp.Xor}[node[1]](a, b)
    if kind == 'not':
        return sp.Not(to_bool(ev(ctx, node[1])))
    if kind == 'cmp':
        return compare(node[1], ev(ctx, node[2]), ev(ctx, node[3]))
    if kind == 'polar':
        r, t = need_expr(ev(ctx, node[1])), need_expr(ev(ctx, node[2]))
        t = t * sp.pi / 180 if ctx.deg else t
        return r * sp.cos(t) + sp.I * r * sp.sin(t)
    if kind == 'conv':
        return convert(ctx, node[1], ev(ctx, node[2]), [ev(ctx, a) for a in node[3]])
    if kind in ('prime', 'primecall'):
        return ev_prime(ctx, node)
    if kind == 'define':
        return define(ctx, node[1], node[2])
    if kind == 'cmd':
        return run_command(ctx, node[1], node[2])
    raise TIError('Syntax: invalid expression')


def to_bool(v: Any) -> Any:
    v = as_expr(v)
    if isinstance(v, TList):
        raise TIError('Data type: boolean expected')
    if not is_bool(v):
        raise TIError('Data type: boolean expected')
    return v


def compare(op: str, a: Any, b: Any) -> Any:
    if isinstance(a, TStr) or isinstance(b, TStr):
        if op in ('=', '≠'):
            same = isinstance(a, TStr) and isinstance(b, TStr) and str(a) == str(b)
            return sp.true if same == (op == '=') else sp.false
        raise TIError('Data type: cannot compare strings')
    if isinstance(a, TList) or isinstance(b, TList):
        if isinstance(a, TList) and isinstance(b, TList):
            if len(a) != len(b):
                raise TIError('Dimension mismatch')
            return TList(compare(op, x, y) for x, y in zip(a, b))
        return TList(compare(op, x, b) for x in a) if isinstance(a, TList) else TList(compare(op, a, y) for y in b)
    if is_mat(a) or is_mat(b):
        if op not in ('=', '≠'):
            raise TIError('Data type: cannot order matrices')
        same = is_mat(a) and is_mat(b) and a.shape == b.shape and (a - b).applyfunc(sp.simplify).is_zero_matrix
        return sp.true if bool(same) == (op == '=') else sp.false
    a, b = as_expr(a), as_expr(b)
    if is_bool(a) or is_bool(b):
        return sp.Equivalent(a, b) if op == '=' else sp.Xor(a, b)
    try:
        if op in ('=', '≠') and a.is_number and b.is_number:
            diff = sp.simplify(a - b) if not (a - b).has(sp.Float) else (a - b)
            zero = diff == 0 or (diff.has(sp.Float) and abs(complex(diff)) < 1e-12)
            return sp.true if bool(zero) == (op == '=') else sp.false
        if op in ('=', '≠') and (a.free_symbols or b.free_symbols):
            return REL[op](a, b, evaluate=False) if a != b else (sp.true if op == '=' else sp.false)
        return REL[op](a, b)
    except TypeError:
        raise TIError('Domain: non-real comparison')


def postfix(ctx: Ctx, op: str, v: Any) -> Any:
    if op == 'ᵀ':
        if not is_mat(v):
            raise TIError('Data type: matrix expected')
        return sp.ImmutableMatrix(v.T)
    if op == '!':
        return map_value(lambda x: sp.factorial(x) if not (x.is_number and x.is_Float) else sp.gamma(x + 1), v)
    if op == '%':
        return map_value(lambda x: x / 100, v)
    if op == '°':
        return v if ctx.deg else map_value(lambda x: x * sp.pi / 180, v)
    raise TIError('Syntax: invalid operator')


def index(v: Any, idx: List[Any]) -> Any:
    try:
        ints = [int(i) for i in idx]
    except (TypeError, ValueError):
        raise TIError('Data type: index must be an integer')
    try:
        if isinstance(v, TList) and len(ints) == 1 and ints[0] >= 1:
            return v[ints[0] - 1]
        if isinstance(v, TStr) and len(ints) == 1 and ints[0] >= 1:
            return TStr(v[ints[0] - 1])
        if is_mat(v) and all(i >= 1 for i in ints):
            if len(ints) == 2:
                return v[ints[0] - 1, ints[1] - 1]
            if len(ints) == 1:
                return sp.ImmutableMatrix(v.row(ints[0] - 1))
    except IndexError:
        pass
    raise TIError('Domain: invalid index')


def ev_name(ctx: Ctx, text: str) -> Any:
    if text.endswith('⁻¹'):
        return binop('^', ev_name(ctx, text[:-2]), sp.Integer(-1))
    key = text.lower()
    if ctx.de and key == ctx.de[0]:
        return ctx.de[2]
    value = ctx.lookup(key)
    if value is not None:
        return value
    if key == 'ans':
        return ctx.vars.get('ans', sp.Integer(0))
    if key == 'true':
        return sp.true
    if key == 'false':
        return sp.false
    if key == 'undef':
        return sp.nan
    return sym(key)


def ev_prime(ctx: Ctx, node: Node) -> Any:
    if not ctx.de or node[1].lower() != ctx.de[0]:
        raise TIError("Syntax: ' is only valid inside deSolve")
    _, x, yf = ctx.de
    order = node[2]
    if node[0] == 'prime':
        return sp.Derivative(yf, (x, order))
    args = node[3]
    if len(args) != 1:
        raise TIError('Argument: initial condition point expected')
    return sp.Subs(sp.Derivative(yf, (x, order)), x, ev(ctx, args[0]))


def cond_parts(node: Node) -> List[Node]:
    if node[0] == 'logic' and node[1] == 'and':
        return cond_parts(node[2]) + cond_parts(node[3])
    return [node]


def ev_with(ctx: Ctx, body: Node, cond: Node) -> Any:
    subs: List[Tuple[sp.Symbol, Any]] = []
    doms: Dict[sp.Symbol, Any] = {}
    names: Set[str] = set()
    for part in cond_parts(cond):
        if part[0] == 'cmp' and part[1] == '=' and part[2][0] == 'name':
            key = part[2][1].lower()
            names.add(key)
            subs.append((sym(key), ev(ctx, part[3])))
            continue
        used = set(names_in(part))
        ctx.shield.append(used)
        try:
            rel = ev(ctx, part)
        finally:
            ctx.shield.pop()
        free = [s for s in getattr(rel, 'free_symbols', set()) if s.name in used]
        if len(free) != 1 or not is_bool(rel):
            raise TIError('Domain: unsupported constraint')
        try:
            region = rel.as_set()
        except Exception:
            raise TIError('Domain: unsupported constraint')
        doms[free[0]] = doms[free[0]].intersect(region) if free[0] in doms else region
        names.add(free[0].name)
    saved = dict(ctx.domain)
    ctx.domain.update(doms)
    ctx.shield.append(names)
    try:
        value = ev(ctx, body)
    finally:
        ctx.shield.pop()
        ctx.domain = saved
    for s, region in doms.items():
        value = map_value(lambda e, s=s, region=region: refine_domain(e, s, region), value)
    for s, val in subs:
        value = substitute(value, s, val)
    return map_value(tidy, value) if subs else value


def refine_domain(e: Any, s: sp.Symbol, region: Any) -> Any:
    if not isinstance(e, sp.Expr) or s not in e.free_symbols:
        return e
    try:
        if region.inf >= 0:
            d = sp.Dummy(positive=True) if region.inf > 0 or not region.contains(0) else sp.Dummy(nonnegative=True)
        elif region.sup <= 0:
            d = sp.Dummy(negative=True) if region.sup < 0 or not region.contains(0) else sp.Dummy(nonpositive=True)
        else:
            return e
        return sp.simplify(e.xreplace({s: d})).xreplace({d: s})
    except Exception:
        return e


def substitute(value: Any, s: sp.Symbol, val: Any) -> Any:
    if isinstance(val, (TList, TStr)) or is_mat(val):
        raise TIError('Data type: constraint value must be an expression')

    def one(e: Any) -> Any:
        if not isinstance(e, sp.Basic):
            return e
        out = e.subs(s, val)
        if isinstance(out, (sp.Integral, sp.Derivative, sp.Sum, sp.Limit)):
            out = out.doit()
        return out

    return map_value(one, value)


def call(ctx: Ctx, name: str, arg_nodes: List[Node]) -> Any:
    key = name.lower()
    if ctx.de and key == ctx.de[0]:
        if len(arg_nodes) != 1:
            raise TIError('Argument: initial condition point expected')
        return ctx.de[2].subs(ctx.de[1], ev(ctx, arg_nodes[0]))
    target = ctx.lookup(key)
    if isinstance(target, UFunc):
        return call_user(ctx, target, [ev(ctx, a) for a in arg_nodes])
    if target is not None and len(arg_nodes) == 1 and key not in FUNCS:
        return binop('*', target, ev(ctx, arg_nodes[0]))
    entry = FUNCS.get(key)
    if entry is None:
        args = [need_expr(as_expr(ev(ctx, a))) for a in arg_nodes]
        return sp.Function(key)(*args)
    fn, opts = entry
    if opts['raw']:
        return fn(ctx, *arg_nodes)
    positions = list(opts['bind']) + (list(range(1, len(arg_nodes))) if opts['bind_rest'] else [])
    shield: Set[str] = set()
    for p in positions:
        if p < len(arg_nodes):
            shield.update(names_in(arg_nodes[p]))
    if shield:
        ctx.shield.append(shield)
    try:
        args = [ev(ctx, a) for a in arg_nodes]
    finally:
        if shield:
            ctx.shield.pop()
    try:
        if opts['listable'] and args and isinstance(args[0], TList):
            return TList(fn(ctx, x, *args[1:]) for x in args[0])
        if opts['listable'] and args and is_mat(args[0]) and len(args) == 1:
            return sp.ImmutableMatrix(args[0].applyfunc(lambda x: fn(ctx, x)))
        return fn(ctx, *args)
    except TypeError as exc:
        if 'positional argument' in str(exc) or 'required' in str(exc):
            raise TIError(f'Argument: wrong number of arguments for {name}')
        raise


def call_user(ctx: Ctx, f: UFunc, args: List[Any]) -> Any:
    if len(args) != len(f.params):
        raise TIError(f'Argument: {f.name} expects {len(f.params)} argument(s)')
    ctx.depth += 1
    if ctx.depth > MAX_DEPTH:
        ctx.depth = 0
        raise TIError('Resource: recursion too deep')
    frame = {p.lower(): a for p, a in zip(f.params, args)}
    ctx.frames.append(frame)
    held, ctx.shield = ctx.shield, []
    try:
        if f.prog is not None:
            from .basic import run_block

            if f.kind == 'func':
                frame['#func'] = True
            try:
                run_block(ctx, f.prog)
            except Control as c:
                if c.kind == 'return':
                    return c.value
                if c.kind != 'stop':
                    raise TIError('Syntax: Exit/Cycle outside a loop')
            return frame.get('#last') if f.kind == 'func' else None
        return ev(ctx, f.body)
    finally:
        ctx.shield = held
        ctx.frames.pop()
        ctx.depth = max(0, ctx.depth - 1)


def define(ctx: Ctx, target: Node, value_node: Node) -> Any:
    kind, name = target[0], target[1]
    key = name.lower()
    if key in FUNCS or key in ('ans', 'true', 'false', 'undef'):
        raise TIError(f'Invalid variable name: {name}')
    if kind == 'ftarget':
        ctx.assign(key, UFunc(key, [p.lower() for p in target[2]], body=value_node, src=ctx.src))
        ctx.changed = True
        return None
    value = finalize(ctx, ev(ctx, value_node), value_node)
    if kind == 'itarget':
        cur = ctx.lookup(key)
        idx = [int(ev(ctx, i)) for i in target[2]]
        if isinstance(cur, TList) and len(idx) == 1 and 1 <= idx[0] <= len(cur) + 1:
            new = TList(cur)
            if idx[0] == len(cur) + 1:
                new.append(value)
            else:
                new[idx[0] - 1] = value
            ctx.assign(key, new)
        elif is_mat(cur) and len(idx) == 2 and 1 <= idx[0] <= cur.rows and 1 <= idx[1] <= cur.cols:
            m = cur.as_mutable()
            m[idx[0] - 1, idx[1] - 1] = value
            ctx.assign(key, sp.ImmutableMatrix(m))
        else:
            raise TIError('Domain: invalid index')
        ctx.changed = True
        return value
    ctx.assign(key, value)
    ctx.changed = True
    return value


def run_command(ctx: Ctx, name: str, args: List[Node]) -> Any:
    fn = CMDS.get(name)
    if fn is None:
        raise TIError(f'Command not available: {name}')
    return fn(ctx, *args)


def convert(ctx: Ctx, name: str, v: Any, args: List[Any]) -> Any:
    if name == 'decimal':
        return approx_value(v)
    if name == 'approxfraction':
        tol = float(args[0]) if args else 5e-14
        return map_value(lambda e: sp.nsimplify(e, rational=True, tolerance=tol) if isinstance(e, sp.Expr) else e, v)
    if name == 'rect':
        return map_value(lambda e: sp.expand_complex(e) if isinstance(e, sp.Expr) else e, v)
    if name == 'polar':
        def polar(e: Any) -> Any:
            r, t = sp.Abs(e), sp.arg(e)
            if ctx.deg:
                t = t * 180 / sp.pi
            return sp.Function('∠')(sp.simplify(r), sp.simplify(t))

        return map_value(polar, v)
    if name in ('exp', 'sin', 'cos', 'ln'):
        target = {'exp': sp.exp, 'sin': sp.sin, 'cos': sp.cos, 'ln': sp.log}[name]
        return map_value(lambda e: e.rewrite(target) if isinstance(e, sp.Expr) else e, v)
    if name == 'rad':
        return map_value(lambda e: e * sp.pi / 180 if ctx.deg else e, v)
    if name == 'dd':
        return map_value(lambda e: e if ctx.deg else e * 180 / sp.pi, v)
    raise TIError(f'Conversion not available: ►{name}')


def evaluate(ctx: Ctx, src: str) -> Any:
    ctx.src = src
    node = parse_statement(src)
    value = ev(ctx, node)
    if node[0] in ('define', 'cmd'):
        return value
    return finalize(ctx, value, node)

