"""Convert MathLive LaTeX into handheld text syntax."""
import re
from typing import List, Optional, Tuple

from .parser import TIError

Tok = Tuple[str, str]
GREEK = {
    'alpha': 'α', 'beta': 'β', 'gamma': 'γ', 'delta': 'δ', 'epsilon': 'ε', 'varepsilon': 'ε', 'zeta': 'ζ', 'eta': 'η', 'theta': 'θ', 'iota': 'ι', 'kappa': 'κ', 'lambda': 'λ', 'mu': 'μ',
    'nu': 'ν', 'xi': 'ξ', 'rho': 'ρ', 'sigma': 'σ', 'tau': 'τ', 'upsilon': 'υ', 'phi': 'φ', 'varphi': 'φ', 'chi': 'χ', 'psi': 'ψ', 'omega': 'ω', 'Gamma': 'Γ', 'Delta': 'Δ', 'Theta': 'Θ',
    'Lambda': 'Λ', 'Xi': 'Ξ', 'Sigma': 'Σ', 'Pi': 'Π', 'Phi': 'Φ', 'Psi': 'Ψ', 'Omega': 'Ω', 'pi': 'π',
}
SIMPLE = {
    'cdot': '*', 'times': '*', 'div': '/', 'le': '≤', 'leq': '≤', 'ge': '≥', 'geq': '≥', 'ne': '≠', 'neq': '≠', 'to': '→', 'rightarrow': '→', 'infty': '∞', 'exponentialE': 'ℯ',
    'imaginaryI': '𝒊', 'differentialD': 'ⅆ', 'angle': '∠', 'blacktriangleright': '►', 'mid': '|', 'vert': '|', 'lbrace': '{', 'rbrace': '}', 'lbrack': '[', 'rbrack': ']', 'lt': '<', 'gt': '>',
    'degree': '°', 'circ': '°', 'prime': "'", 'colon': ':', 'land': ' and ', 'lor': ' or ', 'lnot': ' not ', 'neg': ' not ', 'copyright': '©',
}
SPACES = {',', ' ', ';', ':', '!', 'quad', 'qquad', 'enspace', 'thinspace', 'displaystyle', 'textstyle', 'limits', 'nolimits', 'bigl', 'bigr', 'Bigl', 'Bigr', 'big', 'Big'}
FUNCS = {'sin', 'cos', 'tan', 'sec', 'csc', 'cot', 'sinh', 'cosh', 'tanh', 'ln', 'exp', 'arcsin', 'arccos', 'arctan', 'max', 'min', 'gcd', 'det', 'dim', 'arg', 'lg'}
ALIAS = {'arcsin': 'sin⁻¹', 'arccos': 'cos⁻¹', 'arctan': 'tan⁻¹', 'lg': 'log', 'arg': 'angle'}
DELIMS = {'{': '{', '}': '}', 'lbrace': '{', 'rbrace': '}', 'vert': '|', 'lvert': '|', 'rvert': '|', 'lbrack': '[', 'rbrack': ']', '|': '|'}
ENV_MATRIX = {'bmatrix', 'pmatrix', 'matrix', 'Bmatrix', 'vmatrix', 'smallmatrix'}
CMD_RE = re.compile(r'\\([A-Za-z]+)\*?')
ANY_RE = re.compile(r'\\([A-Za-z]+|.)')


def lex(src: str) -> List[Tok]:
    out: List[Tok] = []
    i = 0
    while i < len(src):
        ch = src[i]
        if ch == '\\':
            m = CMD_RE.match(src, i)
            if m:
                name = m.group(1)
                i = m.end()
                if name in ('left', 'right'):
                    while i < len(src) and src[i] == ' ':
                        i += 1
                    if src.startswith('\\', i):
                        m2 = ANY_RE.match(src, i)
                        delim = DELIMS.get(m2.group(1), '') if m2 else ''
                        i = m2.end() if m2 else i
                    else:
                        delim = src[i] if i < len(src) else ''
                        i += 1
                    if delim == '|':
                        out.append(('abs', 'open' if name == 'left' else 'close'))
                    elif delim and delim != '.':
                        out.append(('ch', delim))
                    continue
                if name in ('lvert', 'rvert'):
                    out.append(('abs', 'open' if name == 'lvert' else 'close'))
                    continue
                out.append(('cmd', name))
                while i < len(src) and src[i] == ' ':
                    i += 1
                continue
            nxt = src[i + 1:i + 2]
            i += 2
            if nxt == '\\':
                out.append(('row', ''))
            elif nxt in SPACES:
                out.append(('ch', ' '))
            else:
                out.append(('ch', nxt))
            continue
        i += 1
        if ch in '{}^_&':
            out.append((ch, ch))
        elif ch == '~':
            out.append(('ch', ' '))
        else:
            out.append(('ch', ch))
    return out


class Conv:
    def __init__(self, toks: List[Tok]):
        self.t = toks
        self.i = 0

    def peek(self) -> Tok:
        return self.t[self.i] if self.i < len(self.t) else ('end', '')

    def until(self, opener: Tok, closer: Tok) -> List[Tok]:
        depth, start = 1, self.i
        while self.i < len(self.t):
            tok = self.t[self.i]
            if tok == opener:
                depth += 1
            elif tok == closer:
                depth -= 1
                if depth == 0:
                    break
            self.i += 1
        inner = self.t[start:self.i]
        self.i += 1
        return inner

    def group_raw(self) -> List[Tok]:
        if self.peek()[0] != '{':
            tok = self.peek()
            if tok[0] == 'end':
                return []
            self.i += 1
            return [tok]
        self.i += 1
        return self.until(('{', '{'), ('}', '}'))

    def arg(self) -> str:
        return Conv(self.group_raw()).seq().strip()

    def raw_text(self) -> str:
        return ''.join(v if k != 'cmd' else '\\' + v for k, v in self.group_raw())

    def skip_spaces(self) -> None:
        while self.peek() == ('ch', ' '):
            self.i += 1

    def operand(self) -> str:
        self.skip_spaces()
        if self.peek() == ('ch', '('):
            self.i += 1
            return Conv(self.until(('ch', '('), ('ch', ')'))).seq().strip()
        rest = self.t[self.i:]
        self.i = len(self.t)
        return Conv(rest).seq().strip()

    def scripts(self) -> Tuple[Optional[str], Optional[str]]:
        sub: Optional[str] = None
        sup: Optional[str] = None
        while self.peek()[0] in ('_', '^'):
            kind = self.peek()[0]
            self.i += 1
            if kind == '_':
                sub = self.arg()
            else:
                sup = self.arg()
        return sub, sup

    def seq(self) -> str:
        out: List[str] = []
        while self.i < len(self.t):
            kind, val = self.t[self.i]
            self.i += 1
            if kind == 'ch':
                out.append(val)
            elif kind == '{':
                self.i -= 1
                out.append(self.arg())
            elif kind == '^':
                a = self.arg()
                if a in ('°', "'", "''"):
                    out.append(a)
                elif a == 'T':
                    out.append('ᵀ')
                elif a == '':
                    raise TIError('Syntax: empty exponent')
                else:
                    out.append(f'^({a})')
            elif kind == '_':
                out.append(self.arg())
            elif kind == 'abs' and val == 'open':
                out.append(f"abs({Conv(self.until(('abs', 'open'), ('abs', 'close'))).seq().strip()})")
            elif kind == '&':
                out.append(',')
            elif kind == 'row':
                out.append(';')
            elif kind == 'cmd':
                out.append(self.command(val))
        return ''.join(out)

    def named(self, name: str) -> str:
        if self.peek()[0] != '^':
            return name
        self.i += 1
        a = self.arg()
        if a in ('-1', '−1'):
            return name + '⁻¹'
        return f'({name}({self.operand()}))^({a})'

    def command(self, name: str) -> str:
        if name in ('frac', 'dfrac', 'tfrac', 'cfrac'):
            a, b = self.arg(), self.arg()
            md = re.fullmatch(r'ⅆ(?:\^\((\d+)\))?', a)
            mb = re.fullmatch(r'ⅆ([^\^]+?)(?:\^\((\d+)\))?', b)
            if md and mb:
                order = md.group(1) or mb.group(2)
                return f'd({self.operand()},{mb.group(1)}' + (f',{order})' if order and order != '1' else ')')
            if a == '' or b == '':
                raise TIError('Syntax: empty fraction box')
            return f'(({a})/({b}))'
        if name == 'sqrt':
            index: Optional[str] = None
            if self.peek() == ('ch', '['):
                self.i += 1
                index = Conv(self.until(('ch', '['), ('ch', ']'))).seq().strip()
            body = self.arg()
            return f'root({body},{index})' if index else f'√({body})'
        if name == 'int':
            return self.integral()
        if name in ('sum', 'prod'):
            sub, sup = self.scripts()
            body = self.operand()
            if not sub or '=' not in sub or not sup or not body:
                raise TIError('Syntax: incomplete sum/product')
            var, lo = sub.split('=', 1)
            return f"{'Σ' if name == 'sum' else 'Π'}({body},{var},{lo},{sup})"
        if name == 'lim':
            sub, _ = self.scripts()
            body = self.operand()
            if not sub or '→' not in sub or not body:
                raise TIError('Syntax: incomplete limit')
            var, point = sub.split('→', 1)
            direction = ''
            m = re.fullmatch(r'(.*?)\^\(([+\-−])\)', point)
            if m:
                point, direction = m.group(1), (',1' if m.group(2) == '+' else ',-1')
            return f'lim({body},{var},{point}{direction})'
        if name == 'log':
            if self.peek()[0] == '_':
                self.i += 1
                base = self.arg()
                return f'log({self.operand()},{base})'
            return self.named('log')
        if name in FUNCS:
            return self.named(ALIAS.get(name, name))
        if name in ('operatorname', 'mathop'):
            return self.named(Conv(self.group_raw()).seq().strip())
        if name in ('mathrm', 'mathit', 'mathbf', 'mathsf', 'mathtt', 'mathnormal', 'boldsymbol', 'bm'):
            inner = Conv(self.group_raw()).seq()
            return {'d': 'ⅆ', 'E': 'ᴇ', 'T': 'T'}.get(inner, inner) if name == 'mathrm' else inner
        if name in ('text', 'textrm', 'mbox', 'textit', 'textbf'):
            return self.raw_text()
        if name == 'placeholder':
            if self.peek() == ('ch', '['):
                self.i += 1
                self.until(('ch', '['), ('ch', ']'))
            if self.peek()[0] == '{':
                self.group_raw()
            raise TIError('Syntax: fill in every template box')
        if name == 'begin':
            return self.environment()
        if name == 'end':
            self.group_raw()
            return ''
        if name in GREEK:
            return GREEK[name]
        if name in SIMPLE:
            return SIMPLE[name]
        if name in SPACES or name in ('left', 'right', 'middle'):
            return ' ' if name in SPACES else ''
        return name

    def integral(self) -> str:
        lo, hi = self.scripts()
        start, depth = self.i, 0
        width = 0
        while self.i < len(self.t):
            tok = self.t[self.i]
            if tok[0] == '{':
                depth += 1
            elif tok[0] == '}':
                depth -= 1
            elif depth == 0 and tok == ('cmd', 'differentialD'):
                width = 1
                break
            elif depth == 0 and tok == ('cmd', 'mathrm') and self.t[self.i + 1:self.i + 4] == [('{', '{'), ('ch', 'd'), ('}', '}')]:
                width = 4
                break
            self.i += 1
        if not width:
            raise TIError('Syntax: integral needs a variable (dx)')
        body = Conv(self.t[start:self.i]).seq().strip()
        self.i += width
        self.skip_spaces()
        var = ''
        kind, val = self.peek()
        if kind == '{':
            var = self.arg()
        elif kind in ('ch', 'cmd'):
            self.i += 1
            var = val if kind == 'ch' else GREEK.get(val, val)
        if not body or not var:
            raise TIError('Syntax: incomplete integral')
        return f'∫({body},{var}' + (f',{lo},{hi})' if lo and hi else ')')

    def environment(self) -> str:
        env = self.raw_text()
        inner = self.until(('cmd', 'begin'), ('cmd', 'end'))
        self.group_raw()
        rows: List[List[List[Tok]]] = [[[]]]
        nest = 0
        for tok in inner:
            if tok == ('cmd', 'begin'):
                nest += 1
            elif tok == ('cmd', 'end'):
                nest -= 1
            if nest == 0 and tok[0] == 'row':
                rows.append([[]])
            elif nest == 0 and tok[0] == '&':
                rows[-1].append([])
            else:
                rows[-1][-1].append(tok)
        cells = [[Conv(c).seq().strip() for c in row] for row in rows]
        cells = [r for r in cells if any(c for c in r)]
        if env in ENV_MATRIX:
            if not cells or any(c == '' for r in cells for c in r):
                raise TIError('Syntax: fill in every matrix element')
            return '[' + ''.join('[' + ','.join(r) + ']' for r in cells) + ']'
        if env in ('cases', 'dcases', 'rcases'):
            parts: List[str] = []
            for r in cells:
                parts.append(r[0])
                cond = re.sub(r'^(if|for|when)\s+', '', (r[1] if len(r) > 1 else '').strip())
                if cond and cond.lower() not in ('otherwise', 'else'):
                    parts.append(cond)
            return f"piecewise({','.join(parts)})"
        return ';'.join(','.join(r) for r in cells)


def to_text(latex: str) -> str:
    text = Conv(lex(latex)).seq().replace('ⅆ', 'd').replace('−', '-')
    return re.sub(r'[ \t]+', ' ', text).strip()

