"""Tokenizer and Pratt parser for handheld CAS syntax. Produces tuple ASTs."""
import re
from typing import Any, List, Optional, Tuple

Node = Tuple[Any, ...]


class TIError(Exception):
    pass


LETTERS = 'A-Za-z_αβγδεζηθικλμνξορστυφχψωΓΔΘΛΞΣΠΦΨΩ'
TOKEN_RE = re.compile(
    r'(?P<ws>[ \t\r\n ]+)'
    r'|(?P<comment>©[^\n]*)'
    r'|(?P<num>(?:\d+\.?\d*|\.\d+)(?:ᴇ[−\-+]?\d+)?)'
    r'|(?P<str>"[^"]*"?)'
    r'|(?P<name>(?:invχ²|χ²[A-Za-z0-9]*|[' + LETTERS + r'][' + LETTERS + r'0-9]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*)(?:⁻¹)?)'
    r'|(?P<op>:=|<=|>=|/=|->|\.\+|\.[\-−]|\.[*·×]|\./|\.\^|⁻¹|[+\-−*·×/÷^!=≠<>≤≥→|,()\[\]{};°%ᵀ&∞πℯ∠√∫\':►²@]|𝒊)'
)
OP_ALIASES = {'−': '-', '·': '*', '×': '*', '÷': '/', '<=': '≤', '>=': '≥', '/=': '≠', '->': '→', '.−': '.-', '.·': '.*', '.×': '.*'}
WORD_OPS = {'and', 'or', 'xor', 'not'}
BLOCK_WORDS = {'then', 'else', 'elseif', 'endif', 'endfor', 'endwhile', 'endloop', 'endfunc', 'endprgm', 'func', 'prgm'}
COMMANDS = {
    'define', 'delvar', 'clearaz', 'clrhist', 'disp', 'lu', 'qr', 'sorta', 'sortd', 'randseed', 'local', 'return', 'request', 'requeststr', 'text',
    'onevar', 'twovar', 'linregmx', 'linregbx', 'medmed', 'quadreg', 'cubicreg', 'quartreg', 'powerreg', 'expreg', 'lnreg', 'sinreg', 'logistic',
    'logisticd', 'ztest', 'ttest', 'ztest_2samp', 'ttest_2samp', 'ztest_1prop', 'ztest_2prop', 'χ²gof', 'χ²2way', 'linregttest', 'zinterval',
    'tinterval', 'zinterval_2samp', 'tinterval_2samp', 'zinterval_1prop', 'zinterval_2prop', 'stop', 'exit', 'cycle', 'unlock', 'lock',
}
REL_OPS = {'=', '≠', '<', '>', '≤', '≥'}


def tokenize(src: str) -> List[Tuple[str, str]]:
    out: List[Tuple[str, str]] = []
    pos = 0
    while pos < len(src):
        m = TOKEN_RE.match(src, pos)
        if not m:
            raise TIError(f'Syntax: unexpected "{src[pos]}"')
        pos = m.end()
        kind = m.lastgroup
        text = m.group()
        if kind in ('ws', 'comment'):
            continue
        if kind == 'op':
            text = OP_ALIASES.get(text, text)
            if text == '²':
                out.append(('op', '^'))
                out.append(('num', '2'))
                continue
            if text == '⁻¹':
                out.append(('op', '^'))
                out.append(('num', '-1'))
                continue
            if text == '@':
                m2 = re.compile(r'(pi|e|i)(?![A-Za-z0-9_])').match(src, pos)
                if not m2:
                    raise TIError('Syntax: unexpected "@"')
                pos = m2.end()
                out.append(('op', {'pi': 'π', 'e': 'ℯ', 'i': '𝒊'}[m2.group(1)]))
                continue
        elif kind == 'num':
            text = text.replace('−', '-').replace('ᴇ', 'e')
        elif kind == 'str':
            text = text[1:-1] if text.endswith('"') and len(text) > 1 else text[1:]
        elif kind == 'name' and text.lower() in WORD_OPS:
            kind, text = 'op', text.lower()
        out.append((kind or 'op', text))
    return out


def split_statements(src: str) -> List[str]:
    parts: List[str] = []
    depth = 0
    quoted = False
    cur = ''
    i = 0
    while i < len(src):
        ch = src[i]
        if ch == '"':
            quoted = not quoted
        elif not quoted:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            elif (ch == '\n' or (ch == ':' and src[i + 1:i + 2] != '=')) and depth <= 0:
                parts.append(cur)
                cur = ''
                i += 1
                continue
        cur += ch
        i += 1
    parts.append(cur)
    return [p.strip() for p in parts if p.strip()]


class Parser:
    def __init__(self, tokens: List[Tuple[str, str]]):
        self.toks = tokens
        self.i = 0

    def peek(self, offset: int = 0) -> Tuple[str, str]:
        j = self.i + offset
        return self.toks[j] if j < len(self.toks) else ('end', '')

    def at_op(self, *ops: str) -> bool:
        kind, text = self.peek()
        return kind == 'op' and text in ops

    def take(self) -> Tuple[str, str]:
        tok = self.peek()
        self.i += 1
        return tok

    def expect(self, op: str) -> None:
        if not self.at_op(op):
            kind, text = self.peek()
            raise TIError(f'Syntax: expected "{op}"' + (f' before "{text}"' if kind != 'end' else ''))
        self.i += 1

    def close(self, op: str) -> None:
        if self.peek()[0] == 'end':
            return
        self.expect(op)

    def statement(self) -> Node:
        kind, text = self.peek()
        if kind == 'name' and text.lower() in COMMANDS and not (self.peek(1) == ('op', '(') or self.peek(1) == ('op', ':=')):
            self.take()
            low = text.lower()
            if low == 'define':
                target = self.target()
                self.expect('=')
                return ('define', target, self.expr())
            args: List[Node] = []
            if self.peek()[0] != 'end':
                args = self.args_until_end()
            return ('cmd', low, args)
        save = self.i
        if kind == 'name':
            try:
                target = self.target()
                if self.at_op(':='):
                    self.take()
                    node: Node = ('define', target, self.expr())
                    self.finish()
                    return node
            except TIError:
                pass
            self.i = save
        node = self.expr()
        while self.at_op('→'):
            self.take()
            node = ('define', self.target(), node)
        self.finish()
        return node

    def finish(self) -> None:
        kind, text = self.peek()
        if kind != 'end':
            raise TIError(f'Syntax: unexpected "{text}"')

    def args_until_end(self) -> List[Node]:
        args = [self.expr()]
        while self.at_op(','):
            self.take()
            args.append(self.expr())
        self.finish()
        return args

    def target(self) -> Node:
        kind, text = self.take()
        if kind != 'name':
            raise TIError('Syntax: variable name expected')
        if self.at_op('('):
            self.take()
            params: List[str] = []
            while not self.at_op(')'):
                pk, pt = self.take()
                if pk != 'name':
                    raise TIError('Syntax: invalid parameter')
                params.append(pt)
                if self.at_op(','):
                    self.take()
            self.expect(')')
            return ('ftarget', text, params)
        if self.at_op('['):
            self.take()
            idx = [self.expr()]
            while self.at_op(','):
                self.take()
                idx.append(self.expr())
            self.expect(']')
            return ('itarget', text, idx)
        return ('vtarget', text)

    def expr(self) -> Node:
        node = self.p_or()
        while self.at_op('|'):
            self.take()
            node = ('with', node, self.p_or())
        return node

    def p_or(self) -> Node:
        node = self.p_and()
        while self.at_op('or', 'xor'):
            op = self.take()[1]
            node = ('logic', op, node, self.p_and())
        return node

    def p_and(self) -> Node:
        node = self.p_not()
        while self.at_op('and'):
            self.take()
            node = ('logic', 'and', node, self.p_not())
        return node

    def p_not(self) -> Node:
        if self.at_op('not'):
            self.take()
            return ('not', self.p_not())
        return self.p_cmp()

    def p_cmp(self) -> Node:
        node = self.p_cat()
        if not self.at_op(*REL_OPS):
            return node
        parts: List[Node] = []
        left = node
        while self.at_op(*REL_OPS):
            op = self.take()[1]
            right = self.p_cat()
            parts.append(('cmp', op, left, right))
            left = right
        out = parts[0]
        for part in parts[1:]:
            out = ('logic', 'and', out, part)
        return out

    def p_cat(self) -> Node:
        node = self.p_add()
        while self.at_op('&'):
            self.take()
            node = ('bin', '&', node, self.p_add())
        return node

    def p_add(self) -> Node:
        node = self.p_mul()
        while self.at_op('+', '-', '.+', '.-'):
            op = self.take()[1]
            node = ('bin', op, node, self.p_mul())
        return node

    def starts_operand(self) -> bool:
        kind, text = self.peek()
        if kind in ('num', 'str'):
            return True
        if kind == 'name':
            return text.lower() not in BLOCK_WORDS
        return kind == 'op' and text in ('(', '{', 'π', 'ℯ', '𝒊', '∞', '√', '∫')

    def p_mul(self) -> Node:
        node = self.p_unary()
        while True:
            if self.at_op('*', '/', '.*', './'):
                op = self.take()[1]
                node = ('bin', op, node, self.p_unary())
            elif self.starts_operand():
                node = ('bin', '*', node, self.p_pow())
            else:
                return node

    def p_unary(self) -> Node:
        if self.at_op('-'):
            self.take()
            return ('neg', self.p_unary())
        if self.at_op('+'):
            self.take()
            return self.p_unary()
        return self.p_pow()

    def p_pow(self) -> Node:
        base = self.p_postfix()
        if self.at_op('^', '.^'):
            op = self.take()[1]
            return ('bin', op, base, self.p_unary())
        return base

    def p_postfix(self) -> Node:
        node = self.p_primary()
        while True:
            if self.at_op('!', '°', '%', 'ᵀ'):
                node = ('post', self.take()[1], node)
            elif self.at_op('['):
                self.take()
                idx = [self.expr()]
                while self.at_op(','):
                    self.take()
                    idx.append(self.expr())
                self.close(']')
                node = ('idx', node, idx)
            elif self.at_op('►'):
                self.take()
                kind, text = self.take()
                if kind != 'name':
                    raise TIError('Syntax: conversion name expected')
                args: List[Node] = []
                if self.at_op('('):
                    self.take()
                    args = self.arglist(')')
                node = ('conv', text.lower(), node, args)
            elif self.at_op('∠'):
                self.take()
                node = ('polar', node, self.p_unary())
            else:
                return node

    def arglist(self, closer: str) -> List[Node]:
        args: List[Node] = []
        if self.at_op(closer):
            self.take()
            return args
        if self.peek()[0] == 'end':
            return args
        args.append(self.expr())
        while self.at_op(','):
            self.take()
            args.append(self.expr())
        self.close(closer)
        return args

    def p_primary(self) -> Node:
        kind, text = self.take()
        if kind == 'num':
            return ('num', text)
        if kind == 'str':
            return ('str', text)
        if kind == 'name':
            primes = 0
            while self.at_op("'"):
                self.take()
                primes += 1
            if self.at_op('('):
                self.take()
                args = self.arglist(')')
                return ('primecall', text, primes, args) if primes else ('call', text, args)
            return ('prime', text, primes) if primes else ('name', text)
        if kind == 'op':
            if text == '(':
                node = self.expr()
                self.close(')')
                return node
            if text == '{':
                return ('list', self.arglist('}'))
            if text == '[':
                return self.matrix()
            if text in ('π', 'ℯ', '𝒊', '∞'):
                return ('const', text)
            if text in ('√', '∫'):
                self.expect('(')
                return ('call', 'sqrt' if text == '√' else '∫', self.arglist(')'))
        raise TIError('Syntax: incomplete expression' if kind == 'end' else f'Syntax: unexpected "{text}"')

    def matrix(self) -> Node:
        rows: List[List[Node]] = []
        if self.at_op('['):
            while self.at_op('['):
                self.take()
                rows.append(self.arglist(']'))
            self.close(']')
            return ('mat', rows)
        row: List[Node] = [self.expr()]
        while True:
            if self.at_op(','):
                self.take()
                row.append(self.expr())
            elif self.at_op(';'):
                self.take()
                rows.append(row)
                row = [self.expr()]
            else:
                break
        rows.append(row)
        self.close(']')
        return ('mat', rows)


def parse_statement(src: str) -> Node:
    tokens = tokenize(src)
    if not tokens:
        raise TIError('Syntax: empty expression')
    return Parser(tokens).statement()


def parse_expr(src: str) -> Node:
    parser = Parser(tokenize(src))
    node = parser.expr()
    parser.finish()
    return node


def names_in(node: Optional[Node]) -> List[str]:
    found: List[str] = []

    def walk(n: Any) -> None:
        if isinstance(n, tuple):
            if n and n[0] == 'name':
                found.append(n[1].lower())
            for part in n[1:]:
                walk(part)
        elif isinstance(n, list):
            for part in n:
                walk(part)

    walk(node)
    return found

