"""Text (re-parsable handheld syntax) and LaTeX output."""
import re
from typing import Any

import sympy as sp
from sympy.printing.latex import LatexPrinter
from sympy.printing.str import StrPrinter

from .values import TList, TStr, UFunc

DIGITS = [6]


def fmt_float(value: Any) -> str:
    try:
        f = float(value)
    except (TypeError, ValueError):
        return 'undef'
    if f != f:
        return 'undef'
    if f in (float('inf'), float('-inf')):
        return '∞' if f > 0 else '-∞'
    if f == 0:
        return '0.'
    digits = DIGITS[0]
    a = abs(f)
    if a >= 10 ** max(digits, 10) or a < 1e-5:
        mant, exp = ('%.*e' % (digits - 1, f)).split('e')
        if '.' in mant:
            mant = mant.rstrip('0')
        return f'{mant}ᴇ{int(exp)}'
    s = '%.*g' % (digits, f)
    if 'e' in s:
        s = '%.0f' % f
    return s if '.' in s else s + '.'


FUNC_NAMES = {
    'asin': 'sin⁻¹', 'acos': 'cos⁻¹', 'atan': 'tan⁻¹', 'asinh': 'sinh⁻¹', 'acosh': 'cosh⁻¹', 'atanh': 'tanh⁻¹', 'asec': 'sec⁻¹', 'acsc': 'csc⁻¹', 'acot': 'cot⁻¹',
    'log': 'ln', 'Abs': 'abs', 're': 'real', 'im': 'imag', 'conjugate': 'conj', 'arg': 'angle', 'binomial': 'nCr', 'Max': 'max', 'Min': 'min', 'Mod': 'mod',
}


def mixed_number(expr: Any) -> Any:
    if len(expr.args) == 2:
        a, b = expr.args
        if a.is_Integer and b.is_Rational and not b.is_Integer:
            return a, b
        if b.is_Integer and a.is_Rational and not a.is_Integer:
            return b, a
    return None


class TextPrinter(StrPrinter):
    def _print_Add(self, expr: Any, order: Any = None) -> str:
        mixed = mixed_number(expr)
        if mixed and mixed[1] > 0:
            return f'{self._print(mixed[0])}+{self._print(mixed[1])}'
        return super()._print_Add(expr, order)

    def _print_Float(self, expr: sp.Float) -> str:
        return fmt_float(expr)

    def _print_Pow(self, expr: Any, rational: bool = False) -> str:
        e = expr.exp
        if e.is_Rational and e.is_negative and e != -1 and e != -sp.Rational(1, 2) and not expr.base.is_number:
            return '1/' + self._print(sp.Pow(expr.base, -e, evaluate=False))
        return super()._print_Pow(expr, rational)

    def _print_Pi(self, expr: Any) -> str:
        return 'π'

    def _print_Exp1(self, expr: Any) -> str:
        return 'ℯ'

    def _print_ImaginaryUnit(self, expr: Any) -> str:
        return '𝒊'

    def _print_Infinity(self, expr: Any) -> str:
        return '∞'

    def _print_NegativeInfinity(self, expr: Any) -> str:
        return '-∞'

    def _print_NaN(self, expr: Any) -> str:
        return 'undef'

    def _print_ComplexInfinity(self, expr: Any) -> str:
        return 'undef'

    def _print_BooleanTrue(self, expr: Any) -> str:
        return 'true'

    def _print_BooleanFalse(self, expr: Any) -> str:
        return 'false'

    def _print_Symbol(self, expr: sp.Symbol) -> str:
        name = expr.name
        return name.lower() if re.fullmatch(r'C\d+', name) else name

    def _print_ExpBase(self, expr: Any) -> str:
        return f'ℯ^({self._print(expr.args[0])})'

    def _print_Function(self, expr: Any) -> str:
        name = expr.func.__name__
        return f"{FUNC_NAMES.get(name, name)}({','.join(self._print(a) for a in expr.args)})"

    def _print_factorial(self, expr: Any) -> str:
        arg = expr.args[0]
        inner = self._print(arg)
        return f'{inner}!' if arg.is_Atom and not arg.is_negative else f'({inner})!'

    def _print_Relational(self, expr: Any) -> str:
        ops = {'==': '=', '!=': '≠', '<=': '≤', '>=': '≥', '<': '<', '>': '>'}
        return f'{self._print(expr.lhs)}{ops.get(expr.rel_op, expr.rel_op)}{self._print(expr.rhs)}'

    def _logic(self, expr: Any, word: str) -> str:
        parts = []
        for a in sort_logic(expr.args):
            s = self._print(a)
            parts.append(f'({s})' if isinstance(a, (sp.Or, sp.And, sp.Xor)) else s)
        return f' {word} '.join(parts)

    def _print_And(self, expr: Any) -> str:
        return self._logic(expr, 'and')

    def _print_Or(self, expr: Any) -> str:
        return self._logic(expr, 'or')

    def _print_Xor(self, expr: Any) -> str:
        return self._logic(expr, 'xor')

    def _print_Not(self, expr: Any) -> str:
        return f'not ({self._print(expr.args[0])})'

    def _print_MatrixBase(self, expr: Any) -> str:
        return '[' + ''.join('[' + ','.join(self._print(v) for v in expr.row(r)) + ']' for r in range(expr.rows)) + ']'

    _print_ImmutableDenseMatrix = _print_MatrixBase
    _print_MutableDenseMatrix = _print_MatrixBase
    _print_ImmutableMatrix = _print_MatrixBase
    _print_Matrix = _print_MatrixBase

    def _print_Piecewise(self, expr: Any) -> str:
        parts = []
        for e, c in expr.args:
            parts.append(self._print(e))
            if c is not sp.true:
                parts.append(self._print(c))
        return f"piecewise({','.join(parts)})"

    def _print_Derivative(self, expr: Any) -> str:
        out = self._print(expr.expr)
        for var, count in expr.variable_count:
            out = f'd({out},{self._print(var)}' + (f',{count})' if count != 1 else ')')
        return out

    def _print_Integral(self, expr: Any) -> str:
        out = self._print(expr.function)
        for lim in expr.limits:
            out = f"∫({out},{','.join(self._print(v) for v in lim)})"
        return out

    def _print_Sum(self, expr: Any) -> str:
        out = self._print(expr.function)
        for lim in expr.limits:
            out = f"Σ({out},{','.join(self._print(v) for v in lim)})"
        return out

    def _print_Product(self, expr: Any) -> str:
        out = self._print(expr.function)
        for lim in expr.limits:
            out = f"Π({out},{','.join(self._print(v) for v in lim)})"
        return out


def sort_logic(args: Any) -> list:
    def key(a: Any) -> tuple:
        if isinstance(a, sp.Equality):
            try:
                v = complex(sp.N(a.rhs))
                return (0, str(a.lhs), v.real, v.imag)
            except (TypeError, ValueError):
                return (1, str(a.lhs), 0.0, 0.0)
        return (2, str(a), 0.0, 0.0)

    try:
        return sorted(args, key=key)
    except TypeError:
        return list(args)


_TEXT = TextPrinter({'order': None})


def expr_text(expr: Any) -> str:
    s = _TEXT.doprint(expr).replace('**', '^').replace('sqrt(', '√(')
    for i, word in enumerate((' and ', ' or ', ' xor ', 'not (')):
        s = s.replace(word, chr(1 + i))
    s = s.replace(' ', '')
    for i, word in enumerate((' and ', ' or ', ' xor ', 'not (')):
        s = s.replace(chr(1 + i), word)
    return s


class TexPrinter(LatexPrinter):
    def _print_Add(self, expr: Any, order: Any = None) -> str:
        mixed = mixed_number(expr)
        if mixed and mixed[1] > 0:
            return f'{self._print(mixed[0])}+{self._print(mixed[1])}'
        return super()._print_Add(expr, order)

    def _print_Float(self, expr: sp.Float) -> str:
        s = fmt_float(expr)
        if 'ᴇ' in s:
            mant, exp = s.split('ᴇ')
            return f'{mant}\\mathrm{{E}}{exp}'
        return s.replace('∞', '\\infty ')

    def _print_NaN(self, expr: Any) -> str:
        return '\\text{undef}'

    def _print_ComplexInfinity(self, expr: Any) -> str:
        return '\\text{undef}'

    def _print_BooleanTrue(self, expr: Any) -> str:
        return '\\text{true}'

    def _print_BooleanFalse(self, expr: Any) -> str:
        return '\\text{false}'

    def _print_Symbol(self, expr: sp.Symbol, style: str = 'plain') -> str:
        name = expr.name
        if re.fullmatch(r'C\d+', name):
            return f'c{name[1:]}'
        if re.fullmatch(r'n\d+', name):
            return f'n{name[1:]}'
        if '.' in name or (len(name) > 1 and name.isalnum() and name.isascii()):
            return f'\\mathrm{{{name}}}'
        return super()._print_Symbol(expr, style) if name.isascii() else name

    def _logic(self, expr: Any, word: str) -> str:
        parts = []
        for a in sort_logic(expr.args):
            s = self._print(a)
            parts.append(f'\\left({s}\\right)' if isinstance(a, (sp.Or, sp.And, sp.Xor)) else s)
        return f'\\text{{ {word} }}'.join(parts)

    def _print_And(self, expr: Any) -> str:
        return self._logic(expr, 'and')

    def _print_Or(self, expr: Any) -> str:
        return self._logic(expr, 'or')

    def _print_Xor(self, expr: Any) -> str:
        return self._logic(expr, 'xor')

    def _print_Not(self, expr: Any) -> str:
        return f'\\text{{not }}\\left({self._print(expr.args[0])}\\right)'


_TEX = TexPrinter({'mul_symbol': 'dot', 'ln_notation': True, 'inv_trig_style': 'power', 'imaginary_unit': 'i', 'mat_delim': '[', 'mat_str': 'bmatrix', 'order': None})


def expr_latex(expr: Any) -> str:
    try:
        return _TEX.doprint(expr)
    except Exception:
        return '\\text{' + expr_text(expr).replace('{', '\\{').replace('}', '\\}') + '}'


def to_text(value: Any) -> str:
    if value is None:
        return 'Done'
    if isinstance(value, TStr):
        return f'"{value}"'
    if isinstance(value, UFunc):
        return 'Done'
    if isinstance(value, TList):
        return '{' + ','.join(to_text(v) for v in value) + '}'
    if isinstance(value, bool):
        return 'true' if value else 'false'
    return expr_text(value)


def to_latex(value: Any) -> str:
    if value is None or isinstance(value, UFunc):
        return '\\text{Done}'
    if isinstance(value, TStr):
        return '\\text{"' + re.sub(r'([#$%&_{}])', r'\\\1', str(value)) + '"}'
    if isinstance(value, TList):
        return '\\left\\{' + ',\\ '.join(to_latex(v) for v in value) + '\\right\\}'
    if isinstance(value, bool):
        return '\\text{true}' if value else '\\text{false}'
    return expr_latex(value)

