"""Value wrappers shared by the evaluator, commands and printers."""
from typing import Any, List, Optional


class TList(list):
    pass


class TStr(str):
    pass


class UFunc:
    def __init__(self, name: str, params: List[str], body: Any = None, prog: Any = None, kind: str = 'func', src: str = ''):
        self.name = name
        self.params = params
        self.body = body
        self.prog = prog
        self.kind = kind
        self.src = src


class NeedInput(Exception):
    def __init__(self, prompt: str, kind: str):
        super().__init__(prompt)
        self.prompt = prompt
        self.kind = kind


class Control(Exception):
    def __init__(self, kind: str, value: Optional[Any] = None):
        super().__init__(kind)
        self.kind = kind
        self.value = value
